module sorted_pair (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire ins,
    input wire rem,
    input wire [7:0] val,
    output reg [1:0] count
);
    reg [7:0] e0, e1, max_shadow;
    initial begin count = 2'd0; e0 = 8'd0; e1 = 8'd0; max_shadow = 8'd0; end

    wire do_ins = i_ce && ins && !rem && (count != 2'd2);
    wire do_rem = i_ce && rem && !ins && (count != 2'd0);

    always @(posedge clk) begin
        if (rst) begin
            count <= 2'd0; e0 <= 8'd0; e1 <= 8'd0; max_shadow <= 8'd0;
        end else if (do_ins) begin
            count <= count + 2'd1;
            if (count == 2'd0) begin
                e0 <= val;  max_shadow <= val;
            end else if (val >= e0) begin
                e1 <= val;  max_shadow <= val;
            end else begin
                e0 <= val;  e1 <= e0;  max_shadow <= e0;
            end
        end else if (do_rem) begin
            count <= count - 2'd1;
            if (count == 2'd2) e0 <= e1;
        end
    end

    always @(posedge clk)
        if (count == 2'd1)
            assert (max_shadow == e0);
endmodule

module gcd_ctrl (
    input  wire       clk,
    input  wire       ce,
    input  wire       start,
    input  wire       ack,
    input  wire [3:0] x,
    input  wire [3:0] y,
    output reg  [3:0] a,
    output reg  [3:0] b,
    output reg        idle,
    output reg        calc,
    output reg        done
);
    initial begin a = 4'd0; b = 4'd0; idle = 1'b1; calc = 1'b0; done = 1'b0; end

    wire finish = (b == 4'd0);

    always @(posedge clk) begin
        if (ce) begin
            idle <= (idle && !start) || (done && ack);
            calc <= (idle && start)  || (calc && !finish);
            done <= (calc && finish) || (done && !ack);

            if (idle && start) begin
                a <= x;
                b <= y;
            end else if (calc && !finish) begin
                if (a >= b) begin
                    a <= a - b;
                end else begin
                    a <= b;
                    b <= a;
                end
            end
        end
    end

    always @(posedge clk)
        if (done)
            assert (!calc);
endmodule

module char_occurrence_scan (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire ch_match,
    output reg [3:0] nchars,
    output reg [3:0] nmatch,
    output wire done
);
    initial nchars = 4'd0;
    initial nmatch = 4'd0;

    // scan a fixed 8-character string, counting occurrences of the target char
    assign done = (nchars == 4'd8);

    always @(posedge clk) begin
        if (rst) begin
            nchars <= 4'd0;
            nmatch <= 4'd0;
        end else if (ce && !done) begin
            nchars <= nchars + 4'd1;
            if (ch_match)
                nmatch <= nmatch + 4'd1;
        end
    end

    // P: if every character matched, the whole string must have been consumed
    always @(posedge clk)
        if (nmatch == 4'd8)
            assert (nchars == 4'd8);
endmodule

module ringq (
    input wire clk,
    input wire rst,
    input wire push,
    input wire pop,
    input wire [7:0] din,
    output wire [7:0] dout,
    output wire full,
    output wire empty
);
    reg [1:0] wptr = 2'd0;
    reg [1:0] rptr = 2'd0;
    reg [2:0] count = 3'd0;
    reg [7:0] mem [0:3];

    assign full  = (count == 3'd4);
    assign empty = (count == 3'd0);

    wire do_push = push && !full;
    wire do_pop  = pop  && !empty;

    always @(posedge clk) begin
        if (rst) begin
            wptr  <= 2'd0;
            rptr  <= 2'd0;
            count <= 3'd0;
        end else begin
            if (do_push) begin
                mem[wptr] <= din;
                wptr <= wptr + 2'd1;
            end
            if (do_pop)
                rptr <= rptr + 2'd1;
            if (do_push && !do_pop)
                count <= count + 3'd1;
            else if (do_pop && !do_push)
                count <= count - 3'd1;
        end
    end

    assign dout = mem[rptr];

    always @(posedge clk)
        if (count == 3'd0) assert (wptr == rptr);
endmodule

module stack_xor (
    input wire clk,
    input wire rst,
    input wire push,
    input wire pop,
    input wire [3:0] data,
    output reg [2:0] sp,
    output reg [3:0] xor_acc
);
    reg [3:0] m0, m1, m2, m3;
    initial begin sp = 0; xor_acc = 0; m0 = 0; m1 = 0; m2 = 0; m3 = 0; end

    wire do_push = push && !pop && (sp != 3'd4);
    wire do_pop  = pop  && !push && (sp != 3'd0);
    wire [3:0] top = (sp == 3'd1) ? m0 : (sp == 3'd2) ? m1 : (sp == 3'd3) ? m2 : m3;

    always @(posedge clk) begin
        if (rst) begin
            sp <= 3'd0;
            xor_acc <= 4'd0;
        end else if (do_push) begin
            case (sp)
                3'd0:    m0 <= data;
                3'd1:    m1 <= data;
                3'd2:    m2 <= data;
                default: m3 <= data;
            endcase
            sp <= sp + 3'd1;
            xor_acc <= xor_acc ^ data;
        end else if (do_pop) begin
            sp <= sp - 3'd1;
            xor_acc <= xor_acc ^ top;
        end
    end

    always @(posedge clk)
        if (sp == 3'd0)
            assert (xor_acc == 4'd0);
endmodule

module ringq (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire push,
    input wire pop
);
    reg [1:0] wptr, rptr;
    reg [2:0] count;
    reg       empty_r, full_r;
    initial begin wptr = 2'd0; rptr = 2'd0; count = 3'd0; empty_r = 1'b1; full_r = 1'b0; end

    wire do_push = i_ce && push && !full_r;
    wire do_pop  = i_ce && pop  && !empty_r;
    wire [1:0] nw = wptr + do_push;
    wire [1:0] nr = rptr + do_pop;

    always @(posedge clk) begin
        if (rst) begin
            wptr <= 2'd0; rptr <= 2'd0; count <= 3'd0;
            empty_r <= 1'b1; full_r <= 1'b0;
        end else begin
            wptr <= nw;
            rptr <= nr;
            empty_r <= (nw == nr) && (do_pop  || (empty_r && !do_push));
            full_r  <= (nw == nr) && (do_push || (full_r  && !do_pop));
            count <= count + do_push - do_pop;
        end
    end

    always @(posedge clk)
        if (empty_r)
            assert (!full_r);
endmodule

module char_tally (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire [7:0] i_char,
    input wire [7:0] i_target,
    output wire o_all_hits,
    output wire o_all_misses
);
    reg [3:0] total, hits, misses;
    initial total  = 4'd0;
    initial hits   = 4'd0;
    initial misses = 4'd0;

    wire match = (i_char == i_target);

    always @(posedge clk)
        if (rst) begin
            total  <= 4'd0;
            hits   <= 4'd0;
            misses <= 4'd0;
        end else if (i_ce && (total != 4'hf)) begin
            total <= total + 4'd1;
            if (match) hits   <= hits   + 4'd1;
            else       misses <= misses + 4'd1;
        end

    assign o_all_hits   = (total != 4'd0) && (hits   == total);
    assign o_all_misses = (total != 4'd0) && (misses == total);

    always @(*)
        if (o_all_hits) assert (!o_all_misses);
endmodule

module stack_ptr_guard (
    input wire clk,
    input wire rst,
    input wire push,
    input wire pop,
    input wire [7:0] din,
    output wire [7:0] dout,
    output reg [2:0] sp,
    output reg empty,
    output reg full
);
    reg [7:0] mem [0:3];

    initial sp    = 3'd0;
    initial empty = 1'b1;
    initial full  = 1'b0;

    assign dout = empty ? 8'h00 : mem[sp - 3'd1];

    always @(posedge clk) begin
        if (rst) begin
            sp    <= 3'd0;
            empty <= 1'b1;
            full  <= 1'b0;
        end else if (push && !pop && !full) begin
            mem[sp] <= din;
            sp      <= sp + 3'd1;
            empty   <= 1'b0;
            full    <= (sp == 3'd3);
        end else if (pop && !push && !empty) begin
            sp    <= sp - 3'd1;
            full  <= 1'b0;
            empty <= (sp == 3'd1);
        end
    end

    always @(posedge clk)
        if (!full) assert (sp <= 3'd4);
endmodule

module qring (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_push,
    input  wire       i_pop,
    output wire       o_full,
    output wire       o_empty
);
    reg [1:0] wptr;
    reg [1:0] rptr;
    reg [2:0] count;

    initial wptr  = 2'd0;
    initial rptr  = 2'd0;
    initial count = 3'd0;

    assign o_full  = (count == 3'd4);
    assign o_empty = (count == 3'd0);

    wire do_push = i_push && !o_full;
    wire do_pop  = i_pop  && !o_empty;

    always @(posedge clk)
        if (rst) begin
            wptr  <= 2'd0;
            rptr  <= 2'd0;
            count <= 3'd0;
        end else begin
            if (do_push) wptr <= wptr + 2'd1;
            if (do_pop)  rptr <= rptr + 2'd1;
            if (do_push && !do_pop) count <= count + 3'd1;
            else if (do_pop && !do_push) count <= count - 3'd1;
        end

    always @(*)
        if (count == 3'd0)
            assert (wptr == rptr);
endmodule

module strcount_pipe (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire flush,
    input wire [7:0] ch,
    output wire [5:0] o_cnt
);
    parameter [7:0] TARGET = 8'h61;

    reg [5:0] total = 6'd0;   // characters accepted
    reg [5:0] cnt   = 6'd0;   // committed occurrences of TARGET
    reg       st_valid = 1'b0; // staged character present
    reg       st_match = 1'b0; // staged character equals TARGET

    wire full   = (total == 6'd63);
    wire accept = ce && !full;

    always @(posedge clk)
        if (rst) begin
            total    <= 6'd0;
            cnt      <= 6'd0;
            st_valid <= 1'b0;
            st_match <= 1'b0;
        end else if (accept) begin
            total    <= total + 6'd1;
            st_valid <= 1'b1;
            st_match <= (ch == TARGET);
            if (st_valid && st_match)
                cnt <= cnt + 6'd1;
        end else if (flush && st_valid) begin
            st_valid <= 1'b0;
            if (st_match)
                cnt <= cnt + 6'd1;
        end

    assign o_cnt = cnt;

    always @(*)
        if (!st_valid)
            assert (cnt <= total);
endmodule

module stack_occupancy (
    input wire clk,
    input wire rst,
    input wire push,
    input wire pop,
    output reg [2:0] sp,
    output reg [2:0] items,
    output reg top_valid
);
    initial sp = 3'd0;
    initial items = 3'd0;
    initial top_valid = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            sp        <= 3'd0;
            items     <= 3'd0;
            top_valid <= 1'b0;
        end else if (push && sp != 3'd4) begin
            sp        <= sp + 3'd1;
            items     <= items + 3'd1;
            top_valid <= 1'b1;
        end else if (pop && sp != 3'd0) begin
            sp        <= sp - 3'd1;
            items     <= items - 3'd1;
            top_valid <= (sp != 3'd1);
        end
    end

    // P: an empty stack (per the occupancy counter) must not advertise a valid top
    always @(posedge clk)
        if (items == 3'd0)
            assert (top_valid == 1'b0);
endmodule

module uart_tx (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire start,
    input wire [7:0] data,
    output reg tx
);
    localparam IDLE = 2'd0, ST = 2'd1, DAT = 2'd2, STP = 2'd3;
    reg [1:0] phase;
    reg [2:0] bit_cnt;
    reg [7:0] sh;
    initial begin phase = IDLE; bit_cnt = 3'd0; sh = 8'h00; tx = 1'b1; end

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE; bit_cnt <= 3'd0; sh <= 8'h00; tx <= 1'b1;
        end else if (ce) begin
            case (phase)
                IDLE: if (start) begin
                          phase <= ST; sh <= data; tx <= 1'b0; bit_cnt <= 3'd0;
                      end
                ST:   begin
                          phase <= DAT; tx <= sh[0]; sh <= {1'b0, sh[7:1]};
                          bit_cnt <= 3'd0;
                      end
                DAT:  if (bit_cnt == 3'd7) begin
                          phase <= STP; tx <= 1'b1; bit_cnt <= 3'd0;
                      end else begin
                          bit_cnt <= bit_cnt + 3'd1; tx <= sh[0];
                          sh <= {1'b0, sh[7:1]};
                      end
                STP:  begin phase <= IDLE; tx <= 1'b1; end
            endcase
        end
    end

    always @(posedge clk)
        if (phase == IDLE)
            assert (bit_cnt == 3'd0);
endmodule

module stack_occupancy (
    input wire clk,
    input wire rst,
    input wire push,
    input wire pop,
    input wire [7:0] data,
    output wire [7:0] o_top,
    output wire empty,
    output wire full
);
    parameter DEPTH = 8;
    reg [3:0] sp   = 4'd0;   // occupancy / stack pointer
    reg [3:0] free = 4'd8;   // mirrored free-slot count
    reg [7:0] mem [0:7];
    integer i;
    initial for (i = 0; i < 8; i = i + 1) mem[i] = 8'h00;

    assign empty = (sp == 4'd0);
    assign full  = (sp == DEPTH[3:0]);

    wire do_push = push && !pop && !full;
    wire do_pop  = pop  && !push && !empty;

    always @(posedge clk)
        if (rst) begin
            sp   <= 4'd0;
            free <= 4'd8;
        end else if (do_push) begin
            sp   <= sp + 4'd1;
            free <= free - 4'd1;
        end else if (do_pop) begin
            sp   <= sp - 4'd1;
            free <= free + 4'd1;
        end

    always @(posedge clk)
        if (!rst && do_push) mem[sp[2:0]] <= data;

    assign o_top = empty ? 8'h00 : mem[sp[2:0] - 3'd1];

    always @(*)
        if (!empty) assert (free <= 4'd7);
endmodule

module intersection_phase_pair (
    input wire clk,
    input wire rst,
    input wire ce,
    output reg [2:0] a_ph,
    output reg [2:0] b_ph,
    output reg [2:0] timer
);
    // phase 0 = GREEN, 1 = YELLOW, 2 = ALL_RED, 3..5 = red while the other road runs
    localparam [2:0] LAST = 3'd5;
    localparam [2:0] DUR  = 3'd4;

    initial a_ph  = 3'd0;
    initial b_ph  = 3'd3;
    initial timer = DUR;

    always @(posedge clk) begin
        if (rst) begin
            a_ph  <= 3'd0;
            b_ph  <= 3'd3;
            timer <= DUR;
        end else if (ce) begin
            if (timer == 3'd0) begin
                a_ph  <= (a_ph == LAST) ? 3'd0 : a_ph + 3'd1;
                b_ph  <= (b_ph == LAST) ? 3'd0 : b_ph + 3'd1;
                timer <= DUR;
            end else begin
                timer <= timer - 3'd1;
            end
        end
    end

    // P: when road A holds its green phase, road B must not also be in its green phase
    always @(posedge clk)
        if (a_ph == 3'd0) assert (b_ph != 3'd0);
endmodule

module token_bucket (
    input wire clk,
    input wire rst,
    input wire drip,
    input wire spend,
    output reg [2:0] tokens,
    output reg tokens_hi
);
    wire drip_en  = drip  && (tokens != 3'd4);
    wire spend_en = spend && (tokens != 3'd0);
    wire inc = drip_en && !spend_en;
    wire dec = spend_en && !drip_en;

    initial tokens   = 3'd0;
    initial tokens_hi = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            tokens    <= 3'd0;
            tokens_hi <= 1'b0;
        end else begin
            if (inc)      tokens <= tokens + 3'd1;
            else if (dec) tokens <= tokens - 3'd1;

            if (inc && tokens == 3'd1)      tokens_hi <= 1'b1;
            else if (dec && tokens == 3'd2) tokens_hi <= 1'b0;
        end
    end

    always @(posedge clk)
        if (tokens_hi) assert (tokens != 3'd0);
endmodule

module wdog_kick (
    input wire clk,
    input wire i_ce,
    input wire kick,
    input wire ack,
    output wire o_reset
);
    reg [3:0] cnt;
    reg zf, armed, fault;
    initial cnt   = 4'd0;
    initial zf    = 1'b1;
    initial armed = 1'b0;
    initial fault = 1'b0;

    always @(posedge clk) if (i_ce) begin
        if (ack) begin
            fault <= 1'b0;
            armed <= 1'b0;
            cnt   <= 4'd0;
            zf    <= 1'b1;
        end else if (kick && !fault) begin
            armed <= 1'b1;
            cnt   <= 4'd8;
            zf    <= 1'b0;
        end else if (armed) begin
            if (zf) fault <= 1'b1;            // expiry seen through the flag
            if (cnt == 4'd0) armed <= 1'b0;   // disarm seen through the count
            else begin
                cnt <= cnt - 4'd1;
                zf  <= (cnt == 4'd1);
            end
        end
    end

    assign o_reset = fault;

    always @(*)
        if (fault) assert (!armed);
endmodule

module thermo_window (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire warmer,
    output reg heat
);
    localparam [3:0] T_LOW  = 4'd4;
    localparam [3:0] T_HIGH = 4'd12;

    reg [3:0] temp;
    reg [1:0] win, heat_cycles, cool_cycles;

    initial begin
        temp = 4'd8; heat = 1'b0;
        win = 2'd0; heat_cycles = 2'd0; cool_cycles = 2'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            temp <= 4'd8; heat <= 1'b0;
            win <= 2'd0; heat_cycles <= 2'd0; cool_cycles <= 2'd0;
        end else if (ce) begin
            win <= win + 2'd1;
            if (heat) heat_cycles <= heat_cycles + 2'd1;
            else      cool_cycles <= cool_cycles + 2'd1;
            temp <= warmer ? ((temp == 4'd15) ? temp : temp + 4'd1)
                           : ((temp == 4'd0)  ? temp : temp - 4'd1);
            if      (temp <= T_LOW)  heat <= 1'b1;
            else if (temp >= T_HIGH) heat <= 1'b0;
        end
    end

    always @(posedge clk)
        if (cool_cycles == 2'd0)
            assert (heat_cycles == win);
endmodule

module strscan (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [7:0] ch,
    input wire [7:0] target,
    output wire done,
    output wire [3:0] hits
);
    parameter LEN = 8;

    reg [3:0] remaining;
    reg [3:0] consumed;
    reg [3:0] match_count;

    initial remaining   = LEN;
    initial consumed    = 0;
    initial match_count = 0;

    always @(posedge clk)
        if (rst) begin
            remaining   <= LEN;
            consumed    <= 0;
            match_count <= 0;
        end else if (ce && (remaining != 4'd0)) begin
            remaining <= remaining - 4'd1;
            consumed  <= consumed  + 4'd1;
            if (ch == target)
                match_count <= match_count + 4'd1;
        end

    assign done = (remaining == 4'd0);
    assign hits = match_count;

    // P: once the whole string has been scanned, every character was consumed
    always @(*)
        if (remaining == 4'd0)
            assert (consumed == LEN);
endmodule

module dma_copier (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [7:0] rd_data,
    output reg  [3:0] wr_addr,
    output reg  [3:0] remaining,
    output reg  [7:0] wr_data,
    output wire       done
);
    localparam [3:0] TOTAL = 4'd8;

    initial wr_addr   = 4'd0;
    initial remaining = TOTAL;
    initial wr_data   = 8'h00;

    assign done = (remaining == 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            wr_addr   <= 4'd0;
            remaining <= TOTAL;
            wr_data   <= 8'h00;
        end else if (ce && remaining != 4'd0) begin
            wr_addr   <= wr_addr + 4'd1;
            remaining <= remaining - 4'd1;
            wr_data   <= rd_data;
        end
    end

    // P: while the block copy is still in flight, the write pointer must stay
    // inside the destination block (0..7).
    always @(posedge clk)
        if (!done)
            assert (wr_addr <= 4'd7);
endmodule

module ring_occ (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    output reg  [2:0] count,
    output reg  [3:0] occ
);
    reg [1:0] wptr, rptr;
    initial begin wptr = 2'd0; rptr = 2'd0; count = 3'd0; occ = 4'b0000; end

    wire do_push = push && (count != 3'd4);
    wire do_pop  = pop  && (count != 3'd0);

    wire [3:0] set_bit = do_push ? (4'b0001 << wptr) : 4'b0000;
    wire [3:0] clr_bit = do_pop  ? (4'b0001 << rptr) : 4'b0000;

    always @(posedge clk) begin
        if (rst) begin
            wptr  <= 2'd0;
            rptr  <= 2'd0;
            count <= 3'd0;
            occ   <= 4'b0000;
        end else begin
            if (do_push) wptr <= wptr + 2'd1;
            if (do_pop)  rptr <= rptr + 2'd1;
            occ <= (occ | set_bit) & ~clr_bit;
            case ({do_push, do_pop})
                2'b10:   count <= count + 3'd1;
                2'b01:   count <= count - 3'd1;
                default: count <= count;
            endcase
        end
    end

    always @(posedge clk)
        if (count == 3'd1)
            assert (occ == 4'b0001 || occ == 4'b0010 ||
                    occ == 4'b0100 || occ == 4'b1000);
endmodule

module rot_shadow (
    input wire clk,
    input wire i_rst,
    input wire i_ce,
    input wire i_load,
    input wire [15:0] i_data,
    output wire [15:0] o_word,
    output wire [15:0] o_shadow
);
    reg [15:0] word   = 16'h0000;
    reg [15:0] shadow = 16'h0000;
    reg [3:0]  amt    = 4'd0;

    always @(posedge clk)
        if (i_rst) begin
            word   <= 16'h0000;
            shadow <= 16'h0000;
            amt    <= 4'd0;
        end else if (i_ce) begin
            if (i_load) begin
                word   <= i_data;
                shadow <= i_data;
                amt    <= 4'd0;
            end else begin
                shadow <= { shadow[14:0], shadow[15] };
                amt    <= amt + 4'd1;
            end
        end

    assign o_word   = word;
    assign o_shadow = shadow;

    always @(*)
        if (amt == 4'd0)
            assert (shadow == word);
endmodule

module lfsr_capture (
    input wire clk,
    input wire rst,
    input wire ce,
    output reg [7:0] out,
    output reg valid
);
    reg [7:0] s = 8'h01;
    wire fb = s[7] ^ s[5] ^ s[4] ^ s[3];

    initial out   = 8'h00;
    initial valid = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            s     <= 8'h01;
            out   <= 8'h00;
            valid <= 1'b0;
        end else if (ce) begin
            s     <= {s[6:0], fb};
            out   <= s;
            valid <= 1'b1;
        end
    end

    always @(posedge clk)
        if (valid) assert (out != 8'h00);
endmodule

module elevator_ctrl (
    input wire clk,
    input wire rst,
    input wire step,
    output reg [1:0] floor,
    output reg dir
);
    // one-hot shadow of the cab position, shifted in lockstep with floor
    reg [3:0] pos;
    initial begin floor = 2'd0; dir = 1'b1; pos = 4'b0001; end

    wire go_up   = step &&  dir && (floor != 2'd3);
    wire go_down = step && !dir && (floor != 2'd0);

    always @(posedge clk) begin
        if (rst) begin
            floor <= 2'd0;
            dir   <= 1'b1;
            pos   <= 4'b0001;
        end else begin
            if (go_up) begin
                floor <= floor + 2'd1;
                pos   <= pos << 1;
            end else if (go_down) begin
                floor <= floor - 2'd1;
                pos   <= pos >> 1;
            end
            if (step) begin
                if (dir && (floor == 2'd3))       dir <= 1'b0;
                else if (!dir && (floor == 2'd0)) dir <= 1'b1;
            end
        end
    end

    always @(posedge clk)
        if (floor == 2'd0)
            assert (pos == 4'b0001);
endmodule

module debounce_stability (
    input wire clk,
    input wire rst,
    input wire sample,
    input wire raw,
    output reg out
);
    reg [2:0] cnt;   // consecutive samples disagreeing with out
    reg [2:0] rem;   // samples still required before out may flip

    initial out = 1'b0;
    initial cnt = 3'd0;
    initial rem = 3'd4;

    always @(posedge clk) begin
        if (rst) begin
            out <= 1'b0;
            cnt <= 3'd0;
            rem <= 3'd4;
        end else if (sample) begin
            if (raw == out) begin
                cnt <= 3'd0;
                rem <= 3'd4;
            end else if (cnt == 3'd4) begin
                out <= raw;
                cnt <= 3'd0;
                rem <= 3'd4;
            end else begin
                cnt <= cnt + 3'd1;
                rem <= rem - 3'd1;
            end
        end
    end

    always @(posedge clk)
        if (cnt == 3'd4) assert (rem != 3'd4);
endmodule

module pwm_antiphase (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire load,
    input wire [3:0] i_duty,
    output wire pwm_a,
    output wire pwm_b
);
    // ramp counter and its anti-phase mirror (kept complementary by construction)
    reg [3:0] cnt  = 4'd0;
    reg [3:0] cntb = 4'd15;
    // duty for each channel, split so the pair always sums to full scale
    reg [3:0] duty_a = 4'd8;
    reg [3:0] duty_b = 4'd7;

    always @(posedge clk)
        if (rst) begin
            cnt  <= 4'd0;
            cntb <= 4'd15;
        end else if (ce) begin
            cnt  <= cnt  + 4'd1;
            cntb <= cntb - 4'd1;
        end

    always @(posedge clk)
        if (rst) begin
            duty_a <= 4'd8;
            duty_b <= 4'd7;
        end else if (load) begin
            duty_a <= i_duty;
            duty_b <= 4'd15 - i_duty;
        end

    assign pwm_a = (cnt  < duty_a);
    assign pwm_b = (cntb < duty_b);

    // the two half-bridge drives must never be asserted together
    always @(*)
        if (pwm_a) assert (!pwm_b);
endmodule

module prio_pipe (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [7:0] req,
    output reg b_valid,
    output reg [2:0] b_idx
);
    reg [7:0] a_vec;
    reg       a_valid;
    reg [7:0] b_vec;

    initial begin
        a_vec = 8'h00; a_valid = 1'b0;
        b_vec = 8'h00; b_idx = 3'd0; b_valid = 1'b0;
    end

    // combinational priority encode of the stage-1 vector (default index 0)
    wire [2:0] a_idx = a_vec[7] ? 3'd7 :
                       a_vec[6] ? 3'd6 :
                       a_vec[5] ? 3'd5 :
                       a_vec[4] ? 3'd4 :
                       a_vec[3] ? 3'd3 :
                       a_vec[2] ? 3'd2 :
                       a_vec[1] ? 3'd1 : 3'd0;

    always @(posedge clk) begin
        if (rst) begin
            a_vec <= 8'h00; a_valid <= 1'b0;
            b_vec <= 8'h00; b_idx <= 3'd0; b_valid <= 1'b0;
        end else if (ce) begin
            a_vec   <= req;
            a_valid <= (req != 8'h00);
            b_vec   <= a_vec;
            b_idx   <= a_idx;
            b_valid <= a_valid;
        end
    end

    always @(posedge clk)
        if (b_valid)
            assert (b_vec[b_idx]);
endmodule

module isqrt_ladder (
    input wire clk,
    input wire rst,
    input wire step,
    output reg [2:0] k,
    output reg [5:0] sq,
    output reg [4:0] odd
);
    initial k   = 3'd0;
    initial sq  = 6'd0;
    initial odd = 5'd1;

    always @(posedge clk) begin
        if (rst) begin
            k   <= 3'd0;
            sq  <= 6'd0;
            odd <= 5'd1;
        end else if (step && k != 3'd7) begin
            k   <= k + 3'd1;
            sq  <= sq + {1'b0, odd};
            odd <= odd + 5'd2;
        end
    end

    // P: when the ladder index reaches 3, the accumulated square must be 9
    always @(posedge clk)
        if (k == 3'd3)
            assert (sq == 6'd9);
endmodule

module gray_cdc_counter (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    output reg  [2:0] bin,
    output reg  [2:0] gray,
    output reg  [2:0] prev_gray,
    output reg        past_ce
);
    initial bin       = 3'd0;
    initial gray      = 3'b000;
    initial prev_gray = 3'b000;
    initial past_ce   = 1'b0;

    wire [2:0] bin_nxt  = bin + 3'd1;
    wire [2:0] gray_nxt = bin_nxt ^ (bin_nxt >> 1);
    wire [2:0] delta    = gray ^ prev_gray;

    always @(posedge clk) begin
        if (rst) begin
            bin       <= 3'd0;
            gray      <= 3'b000;
            prev_gray <= 3'b000;
        end else if (ce) begin
            bin       <= bin_nxt;
            gray      <= gray_nxt;
            prev_gray <= gray;
        end
        past_ce <= ce && !rst;
    end

    // P: after an enabled step, the gray output changed in exactly one bit
    always @(posedge clk)
        if (past_ce)
            assert (delta == 3'b001 || delta == 3'b010 || delta == 3'b100);
endmodule

module vend_credit (
    input  wire clk,
    input  wire i_rst,
    input  wire i_nickel,
    input  wire i_dime,
    output wire o_dispense
);
    // credit counted in 5-cent units toward a 25c (5 unit) item
    reg [2:0] units;
    reg [4:0] credit_1h;   // one-hot shadow of the credit level
    initial units     = 3'd0;
    initial credit_1h = 5'b00001;

    wire       step   = i_nickel | i_dime;
    wire [2:0] amount = i_dime ? 3'd2 : 3'd1;
    wire [3:0] sum    = units + amount;

    assign o_dispense = step && (sum >= 4'd5);

    always @(posedge clk)
        if (i_rst) begin
            units     <= 3'd0;
            credit_1h <= 5'b00001;
        end else if (step) begin
            if (sum >= 4'd5) begin
                units     <= 3'd0;          // vend and clear credit
                credit_1h <= 5'b00001;
            end else begin
                units     <= sum[2:0];
                credit_1h <= i_dime ? (credit_1h << 2) : (credit_1h << 1);
            end
        end

    // P: outside reset the credit shadow is always exactly one-hot
    always @(*)
        if (!i_rst)
            assert ((credit_1h != 5'b00000) &&
                    ((credit_1h & (credit_1h - 5'b00001)) == 5'b00000));
endmodule

module crc8_check (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       din,
    output reg  [7:0] crc,
    output reg        any_one
);
    // bit-serial CRC-8 reduction, polynomial 0x07
    initial begin
        crc     = 8'h00;
        any_one = 1'b0;
    end

    wire fb = crc[7] ^ din;

    always @(posedge clk) begin
        if (rst) begin
            crc     <= 8'h00;
            any_one <= 1'b0;
        end else if (ce) begin
            crc     <= {crc[6:0], 1'b0} ^ (fb ? 8'h07 : 8'h00);
            any_one <= any_one | din;
        end
    end

    // an all-zero stream can never push weight into the high nibble
    always @(posedge clk)
        if (any_one == 1'b0)
            assert (crc[7:4] == 4'h0);
endmodule

module chess_clock (
    input wire clk,
    input wire rst,
    input wire tick,
    input wire press,
    output reg run_w,
    output reg run_b,
    output reg active,
    output reg [2:0] t_w,
    output reg [2:0] t_b
);
    initial run_w  = 1'b1;
    initial run_b  = 1'b0;
    initial active = 1'b1;
    initial t_w    = 3'd5;
    initial t_b    = 3'd5;

    always @(posedge clk) begin
        if (rst) begin
            run_w <= 1'b1; run_b <= 1'b0; active <= 1'b1;
            t_w <= 3'd5;   t_b <= 3'd5;
        end else if (tick && active) begin
            if (press) begin
                run_w <= ~run_w;
                run_b <= ~run_b;
            end
            if (run_w && t_w != 3'd0) t_w <= t_w - 3'd1;
            if (run_b && t_b != 3'd0) t_b <= t_b - 3'd1;
            if ((run_w && t_w == 3'd1) || (run_b && t_b == 3'd1)) begin
                active <= 1'b0;
                run_w  <= 1'b0;
                run_b  <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (active) assert (!(run_w && run_b));
endmodule

module dma_copier (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    output wire       o_done,
    output wire [4:0] o_src_off
);
    parameter [4:0] TOTAL = 5'd20;

    reg [4:0] remaining;
    reg [4:0] sent;
    initial remaining = TOTAL;
    initial sent      = 5'd0;

    always @(posedge clk)
        if (rst) begin
            remaining <= TOTAL;
            sent      <= 5'd0;
        end else if (i_ce && (remaining != 5'd0)) begin
            remaining <= remaining - 5'd1;
            sent      <= sent + 5'd1;
        end

    assign o_done    = (remaining == 5'd0);
    assign o_src_off = sent;

    always @(*)
        if (o_done)
            assert (sent == TOTAL);
endmodule

module lfsr_budget (
    input wire clk,
    input wire rst,
    input wire en,
    output reg [7:0] lfsr,
    output reg [2:0] draws,
    output reg [3:0] bits_used
);
    initial lfsr      = 8'h01;
    initial draws     = 3'd0;
    initial bits_used = 4'd0;

    wire fb = lfsr[7] ^ lfsr[5] ^ lfsr[4] ^ lfsr[3];

    always @(posedge clk) begin
        if (rst) begin
            lfsr      <= 8'h01;
            draws     <= 3'd0;
            bits_used <= 4'd0;
        end else if (en) begin
            if (draws != 3'd7) begin
                lfsr      <= {lfsr[6:0], fb};
                draws     <= draws + 3'd1;
                bits_used <= bits_used + 4'd2;
            end
        end
    end

    always @(posedge clk)
        if (draws != 3'd7)
            assert (bits_used <= 4'd12);
endmodule

module chess_clock (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire press,
    output wire o_frozen
);
    reg [3:0] tA;
    reg [3:0] tB;
    reg [4:0] sum;   // shadow of the combined remaining time
    reg       turn;
    initial tA  = 4'd15;
    initial tB  = 4'd15;
    initial sum = 5'd30;
    initial turn = 1'b0;

    wire frz = (tA == 4'd0) || (tB == 4'd0);
    assign o_frozen = frz;

    always @(posedge clk) begin
        if (rst) begin
            tA   <= 4'd15;
            tB   <= 4'd15;
            sum  <= 5'd30;
            turn <= 1'b0;
        end else if (ce) begin
            if (press)
                turn <= ~turn;
            else if (!frz) begin
                if (turn) tB <= tB - 4'd1;
                else      tA <= tA - 4'd1;
                sum <= sum - 5'd1;
            end
        end
    end

    always @(*)
        if (tA == 4'd0)
            assert (sum == {1'b0, tB});
endmodule

module rr_prio_encoder (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [7:0] req,
    output reg [2:0] ptr,
    output reg vld,
    output reg [2:0] gnt_idx
);
    reg [7:0] mask;
    initial begin ptr = 3'd0; mask = 8'h01; vld = 1'b0; gnt_idx = 3'd0; end

    // the rotating priority slot currently under consideration
    wire hit = |(req & mask);

    always @(posedge clk) begin
        if (rst) begin
            ptr     <= 3'd0;
            mask    <= 8'h01;
            vld     <= 1'b0;
            gnt_idx <= 3'd0;
        end else if (ce) begin
            ptr  <= ptr + 3'd1;
            mask <= {mask[6:0], mask[7]};
            vld  <= hit;
            if (hit) gnt_idx <= ptr;
        end
    end

    always @(posedge clk)
        if (ptr == 3'd0)
            assert (mask == 8'h01);
endmodule

module pwm_dimmer (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [7:0] duty_in,
    output wire pwm_out
);
    reg [7:0] cnt      = 8'd0;   // free-running ramp
    reg [7:0] duty_reg = 8'd0;   // duty latched at period start
    reg [7:0] high_cnt = 8'd0;   // high-time accumulated this period

    always @(posedge clk)
        if (rst) begin
            cnt      <= 8'd0;
            duty_reg <= 8'd0;
            high_cnt <= 8'd0;
        end else if (ce) begin
            if (cnt == 8'd0) begin
                duty_reg <= duty_in;
                high_cnt <= (duty_in != 8'd0) ? 8'd1 : 8'd0;
                cnt      <= 8'd1;
            end else if (cnt == 8'hFF) begin
                cnt      <= 8'd0;
                high_cnt <= 8'd0;
            end else begin
                cnt      <= cnt + 8'd1;
                high_cnt <= high_cnt + ((cnt < duty_reg) ? 8'd1 : 8'd0);
            end
        end

    assign pwm_out = (cnt < duty_reg);

    always @(posedge clk)
        if (pwm_out)
            assert (high_cnt < duty_reg);
endmodule

module watchdog (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire kick,
    input wire ack,
    output reg fault
);
    reg [3:0] timer;
    reg [3:0] elapsed;
    initial begin timer = 4'd8; elapsed = 4'd0; fault = 1'b0; end

    always @(posedge clk) begin
        if (rst) begin
            timer   <= 4'd8;
            elapsed <= 4'd0;
            fault   <= 1'b0;
        end else if (i_ce) begin
            if (ack) begin
                timer   <= 4'd8;
                elapsed <= 4'd0;
                fault   <= 1'b0;
            end else if (kick && !fault) begin
                timer   <= 4'd8;
                elapsed <= 4'd0;
            end else begin
                if (timer != 4'd0)   timer   <= timer - 4'd1;
                if (elapsed != 4'd8) elapsed <= elapsed + 4'd1;
                if (timer == 4'd1)   fault   <= 1'b1;
            end
        end
    end

    always @(posedge clk)
        if (elapsed == 4'd8)
            assert (fault);
endmodule

module alu_accum_slice (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    input  wire       i_sub,
    output reg  [7:0] o_result,
    output wire       o_zero
);
    reg [6:0] half;

    initial o_result = 8'd0;
    initial half     = 7'd0;

    assign o_zero = (o_result == 8'd0);

    always @(posedge clk) begin
        if (rst) begin
            o_result <= 8'd0;
            half     <= 7'd0;
        end else if (i_ce) begin
            o_result <= i_sub ? (o_result - 8'd2) : (o_result + 8'd2);
            half     <= i_sub ? (half     - 7'd1) : (half     + 7'd1);
        end
    end

    // P: whenever the half-step tracker is at zero, the registered ALU result is zero
    always @(posedge clk)
        if (half == 7'd0)
            assert (o_result == 8'd0);
endmodule

module crc8_bitpos (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire din,
    output reg [7:0] crc,
    output wire byte_done
);
    reg [7:0] active;
    reg [2:0] bitcnt;
    reg [7:0] crc_last;

    initial begin
        crc      = 8'hFF;
        active   = 8'h01;
        bitcnt   = 3'd0;
        crc_last = 8'h00;
    end

    wire       fb      = crc[7] ^ din;
    wire [7:0] crc_nxt = {crc[6:0], 1'b0} ^ (fb ? 8'h07 : 8'h00);

    assign byte_done = ce && active[7];

    always @(posedge clk) begin
        if (rst) begin
            crc      <= 8'hFF;
            active   <= 8'h01;
            bitcnt   <= 3'd0;
            crc_last <= 8'h00;
        end else if (ce) begin
            crc    <= crc_nxt;
            active <= {active[6:0], active[7]};
            bitcnt <= bitcnt + 3'd1;
            if (active[7]) crc_last <= crc_nxt;
        end
    end

    always @(posedge clk)
        if (bitcnt == 3'd7)
            assert (active == 8'h80);
endmodule

module sqacc (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    output wire [5:0] o_sq,
    output wire [2:0] o_cnt
);
    // accumulates successive odd numbers, so sq tracks cnt*cnt (mod 64)
    reg [2:0] cnt;
    reg [5:0] sq;
    reg [3:0] odd;

    initial cnt = 3'd0;
    initial sq  = 6'd0;
    initial odd = 4'd1;

    always @(posedge clk)
        if (rst) begin
            cnt <= 3'd0;
            sq  <= 6'd0;
            odd <= 4'd1;
        end else if (step) begin
            cnt <= cnt + 3'd1;
            sq  <= sq + {2'b00, odd};
            odd <= odd + 4'd2;
        end

    assign o_sq  = sq;
    assign o_cnt = cnt;

    // P: at the third index the accumulated value must be the perfect square 9
    always @(*)
        if (cnt == 3'd3)
            assert (sq == 6'd9);
endmodule

module rotstage (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire i_valid,
    input wire [3:0] i_amt,
    input wire [15:0] i_data,
    output wire o_valid,
    output wire [15:0] o_data
);
    reg v0, v1, v2, v3;
    reg [2:0] pend;
    reg [15:0] d0, d1, d2, d3;
    reg [3:0] a0, a1, a2;

    initial begin
        v0 = 0; v1 = 0; v2 = 0; v3 = 0; pend = 0;
        d0 = 0; d1 = 0; d2 = 0; d3 = 0;
        a0 = 0; a1 = 0; a2 = 0;
    end

    always @(posedge clk) begin
        if (rst) begin
            v0 <= 0; v1 <= 0; v2 <= 0; v3 <= 0; pend <= 0;
        end else if (ce) begin
            v0 <= i_valid;
            v1 <= v0;
            v2 <= v1;
            v3 <= v2;
            pend <= pend + (i_valid ? 3'd1 : 3'd0) - (v3 ? 3'd1 : 3'd0);
            d0 <= i_amt[0] ? {i_data[14:0], i_data[15]} : i_data;
            a0 <= i_amt;
            d1 <= a0[1] ? {d0[13:0], d0[15:14]} : d0;
            a1 <= a0;
            d2 <= a1[2] ? {d1[11:0], d1[15:12]} : d1;
            a2 <= a1;
            d3 <= a2[3] ? {d2[7:0], d2[15:8]} : d2;
        end
    end

    assign o_valid = v3;
    assign o_data  = d3;

    always @(posedge clk)
        if (pend == 3'd0) assert (!v3);
endmodule

module sorted_pair (
    input wire clk,
    input wire rst,
    input wire ins,
    input wire pop,
    input wire [3:0] val,
    output reg [4:0] sum
);
    reg [3:0] k0, k1;
    reg [1:0] count;
    initial begin k0 = 0; k1 = 0; count = 0; sum = 0; end

    wire do_ins = ins && !pop && (count != 2'd2);
    wire do_pop = pop && !ins && (count != 2'd0);

    always @(posedge clk) begin
        if (rst) begin
            k0 <= 4'd0; k1 <= 4'd0; count <= 2'd0; sum <= 5'd0;
        end else if (do_ins) begin
            if (count == 2'd0) begin
                k0 <= val;
            end else if (val < k0) begin
                k0 <= val; k1 <= k0;
            end else begin
                k1 <= val;
            end
            count <= count + 2'd1;
            sum   <= sum + {1'b0, val};
        end else if (do_pop) begin
            k0    <= k1;
            k1    <= 4'd0;
            count <= count - 2'd1;
            sum   <= sum - {1'b0, k0};
        end
    end

    always @(posedge clk)
        if (count == 2'd0)
            assert (sum == 5'd0);
endmodule

module token_bucket (
    input  wire clk,
    input  wire rst,
    input  wire ce,
    input  wire req,
    input  wire drip,
    output wire grant
);
    reg [3:0] tokens = 4'd8;   // tokens currently in the bucket
    reg [3:0] free   = 4'd0;   // room left in the bucket (shadow accounting)

    wire spend   = ce && req  && (tokens != 4'd0);
    wire refill  = ce && drip && (free   != 4'd0);

    assign grant = spend;

    always @(posedge clk) begin
        if (rst) begin
            tokens <= 4'd8;
            free   <= 4'd0;
        end else begin
            tokens <= tokens - spend + refill;
            free   <= free   + spend - refill;
        end
    end

    // P: if the bucket is not completely full, at least one slot's worth of
    // tokens is missing, so occupancy cannot exceed CAP-1.
    always @(posedge clk)
        if (free != 4'd0)
            assert (tokens <= 4'd7);
endmodule

module stack_hwm (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire push,
    input wire pop,
    input wire [7:0] din,
    output wire [7:0] top
);
    reg [3:0] sp;
    reg [3:0] hwm;
    reg [7:0] mem [0:15];
    initial begin sp = 4'd0; hwm = 4'd0; end

    wire do_push = ce && push && (sp != 4'd8);
    wire do_pop  = ce && pop  && (sp != 4'd0);
    wire [3:0] nxt = sp + 4'd1;

    assign top = (sp == 4'd0) ? 8'h00 : mem[sp - 4'd1];

    always @(posedge clk) begin
        if (rst) begin
            sp  <= 4'd0;
            hwm <= 4'd0;
        end else begin
            case ({do_push, do_pop})
                2'b10: begin
                    mem[sp] <= din;
                    sp <= nxt;
                    if (nxt > hwm) hwm <= nxt;
                end
                2'b01: sp <= sp - 4'd1;
                default: ;
            endcase
        end
    end

    always @(posedge clk)
        if (sp == 4'd8)
            assert (hwm == 4'd8);
endmodule

module vend_credit (
    input wire clk,
    input wire i_reset,
    input wire i_ce,
    input wire i_dime,
    output wire o_dispense,
    output wire [5:0] o_change
);
    reg [3:0] units = 0;      // credit in 5-cent units
    reg [5:0] cents = 0;      // credit in cents
    reg       dispense = 0;
    reg [5:0] change = 0;

    wire [3:0] inc_u = i_dime ? 4'd2  : 4'd1;
    wire [5:0] inc_c = i_dime ? 6'd10 : 6'd5;
    wire [3:0] nu = units + inc_u;
    wire [5:0] nc = cents + inc_c;

    always @(posedge clk)
        if (i_reset) begin
            units    <= 4'd0;
            cents    <= 6'd0;
            dispense <= 1'b0;
            change   <= 6'd0;
        end else if (i_ce) begin
            if (nu >= 4'd5) begin
                units    <= nu - 4'd5;
                cents    <= nc - 6'd25;
                change   <= nc - 6'd25;
                dispense <= 1'b1;
            end else begin
                units    <= nu;
                cents    <= nc;
                dispense <= 1'b0;
            end
        end

    assign o_dispense = dispense;
    assign o_change   = change;

    always @(posedge clk)
        if (dispense) assert (change <= 6'd5);
endmodule

module substr_search (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [7:0] in_char,
    output reg [1:0] idx,
    output reg found
);
    localparam [7:0] TGT = 8'h61; // 'a'

    initial idx   = 2'd0;
    initial found = 1'b0;

    // matches the 3-character run "aaa"; freezes once idx saturates at 3
    always @(posedge clk) begin
        if (rst) begin
            idx   <= 2'd0;
            found <= 1'b0;
        end else if (ce && idx != 2'd3) begin
            if (in_char == TGT) begin
                idx <= idx + 2'd1;
                if (idx == 2'd2)
                    found <= 1'b1;
            end else begin
                idx <= 2'd0;
            end
        end
    end

    // P: the found flag implies a non-empty partial match is held
    always @(posedge clk)
        if (found) assert (idx != 2'd0);
endmodule

module rr_arbiter_pri (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    input  wire [3:0] req,
    output wire [3:0] gnt,
    output reg  [3:0] pri,
    output reg  [1:0] idx
);
    initial pri = 4'b0001;
    initial idx = 2'd0;

    // only the requester currently pointed at by the rotating priority wins
    assign gnt = req & pri;

    wire low_pri = pri[0] | pri[1];   // priority pointer sits in lower half
    wire idx_hi  = idx[1];            // binary index says upper half

    always @(posedge clk) begin
        if (rst) begin
            pri <= 4'b0001;
            idx <= 2'd0;
        end else if (step) begin
            pri <= {pri[2:0], pri[3]};
            idx <= idx + 2'd1;
        end
    end

    always @(posedge clk)
        if (|gnt)
            assert (!(low_pri && idx_hi));
endmodule

module alu_budget (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire [7:0] i_step,
    output wire [7:0] o_acc,
    output wire o_zero,
    output wire o_full
);
    localparam [7:0] LIMIT = 8'd200;

    reg [7:0] acc;   // accumulated result
    reg [7:0] rem;   // headroom credited to the accumulator
    initial acc = 8'd0;
    initial rem = LIMIT;

    wire grant = i_ce && (rem >= i_step);

    always @(posedge clk)
        if (rst) begin
            acc <= 8'd0;
            rem <= LIMIT;
        end else if (grant) begin
            acc <= acc + i_step;
            rem <= rem - i_step;
        end

    assign o_acc  = acc;
    assign o_zero = (acc == 8'd0);
    assign o_full = (rem == 8'd0);

    // P: a nonzero accumulation never exceeds its saturation bound
    always @(*)
        if (!o_zero) assert (acc <= LIMIT);
endmodule

module chess_clock (
    input  wire clk,
    input  wire ce,
    input  wire rst,
    input  wire press,
    output reg  frozen
);
    // Each side starts with 5 units of time.
    reg [2:0] time_a, time_b;   // remaining time per side
    reg [2:0] spent_a, spent_b; // ticks consumed per side
    reg       turn;             // 0 = side A running, 1 = side B running

    initial begin
        time_a  = 3'd5;
        time_b  = 3'd5;
        spent_a = 3'd0;
        spent_b = 3'd0;
        turn    = 1'b0;
        frozen  = 1'b0;
    end

    always @(posedge clk) begin
        if (ce) begin
            if (rst) begin
                time_a  <= 3'd5;
                time_b  <= 3'd5;
                spent_a <= 3'd0;
                spent_b <= 3'd0;
                turn    <= 1'b0;
                frozen  <= 1'b0;
            end else if (!frozen) begin
                if (press) begin
                    // hand over the move: exactly one side runs at a time
                    turn <= ~turn;
                end else if (turn == 1'b0) begin
                    time_a  <= time_a  - 1'b1;
                    spent_a <= spent_a + 1'b1;
                    if (time_a == 3'd1)
                        frozen <= 1'b1;
                end else begin
                    time_b  <= time_b  - 1'b1;
                    spent_b <= spent_b + 1'b1;
                    if (time_b == 3'd1)
                        frozen <= 1'b1;
                end
            end
        end
    end

    // P: the clock only freezes once some side has burned its full allowance.
    always @(posedge clk)
        if (frozen)
            assert (spent_a == 3'd5 || spent_b == 3'd5);
endmodule

module ring_valid_onehot (
    input wire        clk,
    input wire        rst,
    input wire        push,
    input wire        pop,
    input wire [7:0]  din,
    output wire [7:0] dout,
    output wire       o_empty,
    output wire       o_full
);
    // 4-deep ring buffer with a per-slot valid bit vector
    reg [1:0] wptr;
    reg [1:0] rptr;
    reg [2:0] count;
    reg [3:0] valid;
    reg [7:0] mem [0:3];

    integer k;
    initial begin
        wptr  = 2'd0;
        rptr  = 2'd0;
        count = 3'd0;
        valid = 4'b0000;
        for (k = 0; k < 4; k = k + 1)
            mem[k] = 8'h00;
    end

    wire do_push = push && (count != 3'd4);
    wire do_pop  = pop  && (count != 3'd0);

    assign o_empty = (count == 3'd0);
    assign o_full  = (count == 3'd4);
    assign dout    = mem[rptr];

    always @(posedge clk) begin
        if (rst) begin
            wptr  <= 2'd0;
            rptr  <= 2'd0;
            count <= 3'd0;
            valid <= 4'b0000;
        end else begin
            if (do_push) begin
                mem[wptr]   <= din;
                valid[wptr] <= 1'b1;
                wptr        <= wptr + 2'd1;
            end
            if (do_pop) begin
                valid[rptr] <= 1'b0;
                rptr        <= rptr + 2'd1;
            end
            if (do_push && !do_pop)
                count <= count + 3'd1;
            else if (!do_push && do_pop)
                count <= count - 3'd1;
        end
    end

    // occupancy window implied by (rptr, count): slot i is occupied iff
    // ((i - rptr) mod 4) < count
    wire [1:0] d0 = 2'd0 - rptr;
    wire [1:0] d1 = 2'd1 - rptr;
    wire [1:0] d2 = 2'd2 - rptr;
    wire [1:0] d3 = 2'd3 - rptr;
    wire [3:0] occ;
    assign occ[0] = ({1'b0, d0} < count);
    assign occ[1] = ({1'b0, d1} < count);
    assign occ[2] = ({1'b0, d2} < count);
    assign occ[3] = ({1'b0, d3} < count);

    // P: a single-entry queue has exactly one valid slot
    always @(*)
        if (count == 3'd1)
            assert ((valid == 4'b0001) || (valid == 4'b0010) ||
                    (valid == 4'b0100) || (valid == 4'b1000));
endmodule

module debounce_shadow (
    input  wire clk,
    input  wire rst,
    input  wire ce,      // sample enable: low => design idles, no state changes
    input  wire raw,     // raw (noisy) button input
    output reg  out      // debounced output
);
    // stability counter (binary) and its one-hot phase shadow
    reg [1:0] cnt;
    reg [3:0] oh;

    reg       sync;        // last sampled level
    reg       out_shadow;  // shadow copy of out, driven off the one-hot path
    reg       out_valid;   // set once a debounced decision has been taken

    initial begin
        cnt        = 2'd0;
        oh         = 4'b0001;
        sync       = 1'b0;
        out        = 1'b0;
        out_shadow = 1'b0;
        out_valid  = 1'b0;
    end

    wire match = (raw == sync);

    always @(posedge clk) begin
        if (rst) begin
            cnt        <= 2'd0;
            oh         <= 4'b0001;
            sync       <= raw;
            out        <= 1'b0;
            out_shadow <= 1'b0;
            out_valid  <= 1'b0;
        end else if (ce) begin
            if (!match) begin
                // input changed: restart the stability measurement
                sync <= raw;
                cnt  <= 2'd0;
                oh   <= 4'b0001;
            end else begin
                // advance binary counter (saturating)
                if (cnt != 2'd3)
                    cnt <= cnt + 2'd1;
                // advance one-hot phase (saturating in the top position)
                if (!oh[3])
                    oh <= oh << 1;
                // decision taken from the BINARY path
                if (cnt == 2'd3) begin
                    out       <= sync;
                    out_valid <= 1'b1;
                end
                // decision taken from the ONE-HOT path
                if (oh[3])
                    out_shadow <= sync;
            end
        end
    end

    // P: once a debounced decision exists, the shadow must agree with the output
    always @(posedge clk)
        if (out_valid)
            assert (out == out_shadow);
endmodule

module vend_credit (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_coin_valid,   // idle when low: all state frozen
    input  wire       i_coin_dime,    // 1 = 10c, 0 = 5c
    output reg        o_dispense,
    output reg  [5:0] o_change
);
    // credit in cents, always a multiple of 5, capped by the 25c price
    reg [5:0] credit;
    // redundant "nickel units" accumulator: credit / 5
    reg [2:0] units;

    initial credit     = 6'd0;
    initial units      = 3'd0;
    initial o_dispense = 1'b0;
    initial o_change   = 6'd0;

    // coin value, in units and in cents
    wire [2:0] coin_u = i_coin_valid ? (i_coin_dime ? 3'd2 : 3'd1) : 3'd0;
    wire [5:0] coin_c = i_coin_valid ? (i_coin_dime ? 6'd10 : 6'd5) : 6'd0;

    wire [3:0] usum = {1'b0, units}  + {1'b0, coin_u};
    wire [6:0] csum = {1'b0, credit} + {1'b0, coin_c};

    // the dispense decision is taken on the units accumulator
    wire       pay   = (usum >= 4'd5);

    always @(posedge clk) begin
        if (rst) begin
            credit     <= 6'd0;
            units      <= 3'd0;
            o_dispense <= 1'b0;
            o_change   <= 6'd0;
        end else if (i_coin_valid) begin
            if (pay) begin
                units      <= usum[2:0] - 3'd5;
                credit     <= csum[5:0] - 6'd25;
                o_dispense <= 1'b1;
                o_change   <= csum[5:0] - 6'd25;
            end else begin
                units      <= usum[2:0];
                credit     <= csum[5:0];
                o_dispense <= 1'b0;
            end
        end else begin
            o_dispense <= 1'b0;
        end
    end

    // P: when the units accumulator sits one nickel short of the price,
    //    the cent accumulator must read exactly 20 cents.
    always @(*)
        if (units == 3'd4)
            assert (credit == 6'd20);
endmodule

module token_bucket_ledger (
    input  wire       clk,
    input  wire       rst,
    input  wire       drip_en,
    input  wire       grant_req,
    output wire       grant,
    output wire       dry
);
    localparam [3:0] CAP = 4'd8;

    // bucket level
    reg [3:0] tokens = 4'd0;
    // free-running mod-16 ledgers of every accepted drip and every issued grant
    reg [3:0] drips  = 4'd0;
    reg [3:0] grants = 4'd0;

    wire do_drip  = drip_en   && (tokens < CAP);
    wire do_grant = grant_req && (tokens != 4'd0);

    assign grant = do_grant;
    assign dry   = (tokens == 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            tokens <= 4'd0;
            drips  <= 4'd0;
            grants <= 4'd0;
        end else begin
            if (do_drip && !do_grant)
                tokens <= tokens + 4'd1;
            else if (!do_drip && do_grant)
                tokens <= tokens - 4'd1;

            if (do_drip)
                drips <= drips + 4'd1;
            if (do_grant)
                grants <= grants + 4'd1;
        end
    end

    // P: whenever the two ledgers agree, the bucket must be empty
    always @(posedge clk)
        if (drips == grants)
            assert (tokens == 4'd0);
endmodule

module uart_tx_budget (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // baud tick / enable: low means idle
    input  wire       i_start,
    input  wire [7:0] i_data,
    output reg        tx,
    output reg        busy
);
    // bit accounting for one 8-bit payload
    reg [3:0] sent;   // data bits already shifted out
    reg [3:0] left;    // data bits still to shift out
    reg [7:0] sh;      // shift register

    initial tx   = 1'b1;
    initial busy = 1'b0;
    initial sent = 4'd0;
    initial left = 4'd8;
    initial sh   = 8'h00;

    always @(posedge clk) begin
        if (rst) begin
            tx   <= 1'b1;
            busy <= 1'b0;
            sent <= 4'd0;
            left <= 4'd8;
            sh   <= 8'h00;
        end else if (i_ce) begin
            if (!busy) begin
                if (i_start) begin
                    busy <= 1'b1;
                    sh   <= i_data;
                    sent <= 4'd0;
                    left <= 4'd8;
                    tx   <= 1'b0;      // start bit
                end else begin
                    tx   <= 1'b1;      // line idle high
                end
            end else if (left != 4'd0) begin
                tx   <= sh[0];         // data bit
                sh   <= {1'b0, sh[7:1]};
                sent <= sent + 4'd1;
                left <= left - 4'd1;
            end else begin
                tx   <= 1'b1;          // stop bit, frame complete
                busy <= 1'b0;
            end
        end
    end

    // Property: whenever the transmitter reports no data bits remaining while a
    // frame is still active, exactly eight payload bits must have been shifted.
    always @(posedge clk)
        if (busy && left == 4'd0)
            assert (sent == 4'd8);
endmodule

module crc8_bitpos_check (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       bit_in,
    output wire [7:0] o_crc,
    output wire [7:0] o_byte,
    output wire       o_byte_done
);
    parameter [7:0] POLY = 8'h07;

    // streaming CRC-8 remainder, one bit per cycle
    reg [7:0] crc;
    // one-hot pointer marking which bit slot of the byte is being filled
    reg [7:0] mask;
    // bit index within the current byte
    reg [2:0] cnt;
    // byte under assembly
    reg [7:0] byte_sr;

    initial crc     = 8'h00;
    initial mask    = 8'h01;
    initial cnt     = 3'd0;
    initial byte_sr = 8'h00;

    wire fb = crc[7] ^ bit_in;

    always @(posedge clk) begin
        if (rst) begin
            crc     <= 8'h00;
            mask    <= 8'h01;
            cnt     <= 3'd0;
            byte_sr <= 8'h00;
        end else if (ce) begin
            crc     <= { crc[6:0], 1'b0 } ^ (fb ? POLY : 8'h00);
            mask    <= { mask[6:0], mask[7] };
            cnt     <= cnt + 3'd1;
            byte_sr <= (byte_sr & ~mask) | (bit_in ? mask : 8'h00);
        end
    end

    assign o_crc       = crc;
    assign o_byte      = byte_sr;
    assign o_byte_done = ce && (cnt == 3'd7);

    // P: at a byte boundary the fill pointer must point at bit 0
    always @(posedge clk)
        if (cnt == 3'd0)
            assert (mask == 8'h01);
endmodule

module rr_arb (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,       // enable: low means the arbiter idles
    input  wire [3:0] req,
    output reg  [3:0] grant,
    output reg        gnt_valid
);
    reg [1:0] ptr;      // round-robin priority pointer
    reg [1:0] gnt_id;   // id of the currently granted requester

    initial begin
        grant     = 4'b0000;
        gnt_valid = 1'b0;
        ptr       = 2'd0;
        gnt_id    = 2'd0;
    end

    // rotate the request vector by the priority pointer
    wire [3:0] rreq;
    assign rreq[0] = req[ptr];
    assign rreq[1] = req[ptr + 2'd1];
    assign rreq[2] = req[ptr + 2'd2];
    assign rreq[3] = req[ptr + 2'd3];

    wire [1:0] roff = rreq[0] ? 2'd0 :
                      rreq[1] ? 2'd1 :
                      rreq[2] ? 2'd2 : 2'd3;

    wire       win_valid = |req;
    wire [1:0] win_id    = ptr + roff;

    // one-hot masks derived from the recorded ids
    wire [3:0] old_mask = 4'b0001 << gnt_id;
    wire [3:0] new_mask = 4'b0001 << win_id;

    always @(posedge clk) begin
        if (rst) begin
            grant     <= 4'b0000;
            gnt_valid <= 1'b0;
            ptr       <= 2'd0;
            gnt_id    <= 2'd0;
        end else if (step) begin
            if (win_valid) begin
                // release the previously granted line, assert the new one
                grant     <= (grant & ~old_mask) | new_mask;
                gnt_id    <= win_id;
                gnt_valid <= 1'b1;
                ptr       <= win_id + 2'd1;
            end else begin
                grant     <= grant & ~old_mask;
                gnt_valid <= 1'b0;
            end
        end
    end

    // P: while a grant is outstanding, no two grant lines are high together
    always @(posedge clk)
        if (gnt_valid)
            assert (grant == 4'b0001 || grant == 4'b0010 ||
                    grant == 4'b0100 || grant == 4'b1000);
endmodule

module stack_mask (
    input  wire       clk,
    input  wire       rst,
    input  wire       en,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] din,
    output wire [7:0] dout,
    output wire       empty,
    output wire       full,
    output reg  [3:0] sp
);
    // occupancy mask: bit i is set iff slot i currently holds data.
    // maintained purely by shifting, never recomputed from sp.
    reg [7:0] occ;
    reg [7:0] mem0, mem1, mem2, mem3, mem4, mem5, mem6, mem7;

    initial begin
        sp   = 4'd0;
        occ  = 8'h00;
        mem0 = 8'h00; mem1 = 8'h00; mem2 = 8'h00; mem3 = 8'h00;
        mem4 = 8'h00; mem5 = 8'h00; mem6 = 8'h00; mem7 = 8'h00;
    end

    assign empty = (sp == 4'd0);
    assign full  = (sp == 4'd8);

    wire do_push = en && push && !pop && !full;
    wire do_pop  = en && pop  && !push && !empty;

    wire [2:0] top = sp[2:0] - 3'd1;

    assign dout = empty ? 8'h00 :
                  (top == 3'd0) ? mem0 :
                  (top == 3'd1) ? mem1 :
                  (top == 3'd2) ? mem2 :
                  (top == 3'd3) ? mem3 :
                  (top == 3'd4) ? mem4 :
                  (top == 3'd5) ? mem5 :
                  (top == 3'd6) ? mem6 : mem7;

    always @(posedge clk) begin
        if (rst) begin
            sp  <= 4'd0;
            occ <= 8'h00;
        end else if (do_push) begin
            sp  <= sp + 4'd1;
            occ <= {occ[6:0], 1'b1};
        end else if (do_pop) begin
            sp  <= sp - 4'd1;
            occ <= {1'b0, occ[7:1]};
        end
    end

    always @(posedge clk) begin
        if (!rst && do_push) begin
            case (sp[2:0])
                3'd0: mem0 <= din;
                3'd1: mem1 <= din;
                3'd2: mem2 <= din;
                3'd3: mem3 <= din;
                3'd4: mem4 <= din;
                3'd5: mem5 <= din;
                3'd6: mem6 <= din;
                3'd7: mem7 <= din;
            endcase
        end
    end

    // P: an empty stack must own no slots.
    always @(posedge clk)
        if (sp == 4'd0)
            assert (occ == 8'h00);
endmodule

module elevator_cab (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,        // idle condition: low freezes all state
    input  wire       req_valid,
    input  wire [1:0] req_floor,
    output reg  [1:0] floor,
    output reg  [1:0] target,
    output reg  [1:0] dist,        // remaining floors of travel
    output reg        dir,         // 1 = up, 0 = down
    output reg        busy         // cab is in transit
);
    initial floor  = 2'd0;
    initial target = 2'd0;
    initial dist   = 2'd0;
    initial dir    = 1'b0;
    initial busy   = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            floor  <= 2'd0;
            target <= 2'd0;
            dist   <= 2'd0;
            dir    <= 1'b0;
            busy   <= 1'b0;
        end else if (step) begin
            if (busy) begin
                // one floor of travel per step
                if (dir)
                    floor <= floor + 2'd1;
                else
                    floor <= floor - 2'd1;
                dist <= dist - 2'd1;
                if (dist == 2'd1)
                    busy <= 1'b0;
            end else if (req_valid && (req_floor != floor)) begin
                target <= req_floor;
                dir    <= (req_floor > floor);
                dist   <= (req_floor > floor) ? (req_floor - floor)
                                              : (floor - req_floor);
                busy   <= 1'b1;
            end
        end
    end

    // P: whenever the cab is not in transit, it is parked at its target floor
    always @(posedge clk)
        if (!busy)
            assert (floor == target);
endmodule

module queue_ring_onehot (
    input  wire clk,
    input  wire rst,
    input  wire push,
    input  wire pop,
    input  wire [7:0] wdata,
    output wire [7:0] rdata,
    output wire full,
    output wire empty
);
    // 4-entry ring buffer.  The write and read positions are kept as one-hot
    // slot selects that rotate; the occupancy is kept as a separate counter.
    reg [2:0] count;
    reg [3:0] wsel;
    reg [3:0] rsel;
    reg [7:0] mem0, mem1, mem2, mem3;

    initial count = 3'd0;
    initial wsel  = 4'b0001;
    initial rsel  = 4'b0001;
    initial mem0  = 8'h00;
    initial mem1  = 8'h00;
    initial mem2  = 8'h00;
    initial mem3  = 8'h00;

    assign full  = (count == 3'd4);
    assign empty = (count == 3'd0);

    wire do_push = push && (count != 3'd4);
    wire do_pop  = pop  && (count != 3'd0);

    assign rdata = rsel[0] ? mem0 :
                   rsel[1] ? mem1 :
                   rsel[2] ? mem2 : mem3;

    always @(posedge clk) begin
        if (rst) begin
            count <= 3'd0;
            wsel  <= 4'b0001;
            rsel  <= 4'b0001;
        end else begin
            if (do_push && !do_pop)
                count <= count + 3'd1;
            else if (do_pop && !do_push)
                count <= count - 3'd1;

            if (do_push)
                wsel <= { wsel[2:0], wsel[3] };

            if (do_pop)
                rsel <= { rsel[2:0], rsel[3] };
        end
    end

    always @(posedge clk) begin
        if (!rst && do_push) begin
            if (wsel[0]) mem0 <= wdata;
            if (wsel[1]) mem1 <= wdata;
            if (wsel[2]) mem2 <= wdata;
            if (wsel[3]) mem3 <= wdata;
        end
    end

    // P: an empty ring must have its write slot select aligned with its read
    // slot select.
    always @(*)
        if (count == 3'd0)
            assert (wsel == rsel);
endmodule

module lfsr_shadow_capture (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_cap,
    output wire [7:0] o_rand,
    output wire [7:0] o_shadow,
    output wire       o_shadow_valid
);
    // maximal-length 8-bit LFSR, taps at 8,6,5,4 (x^8 + x^6 + x^5 + x^4 + 1)
    reg [7:0] lfsr;
    reg [7:0] shadow;
    reg       shadow_valid;

    initial lfsr         = 8'h01;
    initial shadow       = 8'h00;
    initial shadow_valid = 1'b0;

    wire fb = lfsr[7] ^ lfsr[5] ^ lfsr[4] ^ lfsr[3];

    always @(posedge i_clk) begin
        if (i_rst) begin
            lfsr <= 8'h01;
        end else if (i_ce) begin
            lfsr <= { lfsr[6:0], fb };
        end
    end

    // shadow register: snapshots the generator output on request
    always @(posedge i_clk) begin
        if (i_rst) begin
            shadow       <= 8'h00;
            shadow_valid <= 1'b0;
        end else if (i_ce && i_cap) begin
            shadow       <= lfsr;
            shadow_valid <= 1'b1;
        end
    end

    assign o_rand         = lfsr;
    assign o_shadow       = shadow;
    assign o_shadow_valid = shadow_valid;

    // P: once a sample has been latched, it can never be the lockup word
    always @(*)
        if (shadow_valid)
            assert (shadow != 8'h00);
endmodule

module gray_cdc_counter (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    output reg  [3:0] gray
);
    // shadow binary counter
    reg [3:0] bin;
    // previous emitted gray value, and a sticky flag saying one step happened
    reg [3:0] gray_prev;
    reg       changed;

    initial bin       = 4'd0;
    initial gray      = 4'b0000;
    initial gray_prev = 4'b0000;
    initial changed   = 1'b0;

    wire [3:0] bin_nxt  = bin + 4'd1;
    wire [3:0] gray_nxt = bin_nxt ^ (bin_nxt >> 1);

    always @(posedge clk) begin
        if (rst) begin
            bin       <= 4'd0;
            gray      <= 4'b0000;
            gray_prev <= 4'b0000;
            changed   <= 1'b0;
        end else if (step) begin
            bin       <= bin_nxt;
            gray      <= gray_nxt;
            gray_prev <= gray;
            changed   <= 1'b1;
        end
    end

    // P: once a step has been taken, the current and previous gray words
    //    differ in exactly one bit (safe for clock-domain crossing).
    wire [3:0] diff = gray ^ gray_prev;

    always @(posedge clk) begin
        if (changed)
            assert ((diff != 4'b0000) && ((diff & (diff - 4'd1)) == 4'b0000));
    end
endmodule

module thermo_hyst (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    output reg        heat_on,
    output reg [2:0]  on_events,
    output reg [2:0]  off_events
);
    localparam [5:0] T_LOW  = 6'd20;
    localparam [5:0] T_HIGH = 6'd40;

    reg [5:0] temp;

    initial begin
        temp       = 6'd30;
        heat_on    = 1'b0;
        on_events  = 3'd0;
        off_events = 3'd0;
    end

    // hysteresis decisions
    wire turn_on  = ce && !heat_on && (temp <= T_LOW);
    wire turn_off = ce &&  heat_on && (temp >= T_HIGH);

    always @(posedge clk) begin
        if (rst) begin
            temp       <= 6'd30;
            heat_on    <= 1'b0;
            on_events  <= 3'd0;
            off_events <= 3'd0;
        end else if (ce) begin
            if (turn_on) begin
                heat_on   <= 1'b1;
                on_events <= on_events + 3'd1;
            end else if (turn_off) begin
                heat_on    <= 1'b0;
                off_events <= off_events + 3'd1;
            end

            // plant: heater warms, ambient cools
            if (heat_on) begin
                if (temp != 6'd63) temp <= temp + 6'd1;
            end else begin
                if (temp != 6'd0)  temp <= temp - 6'd1;
            end
        end
    end

    // P: whenever the heater is commanded on, strictly more on-events than
    // off-events have been logged, so the two event counters cannot agree.
    always @(posedge clk)
        if (heat_on)
            assert (on_events != off_events);

endmodule

module dma_copier (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    output reg  [3:0] remaining,
    output reg  [3:0] sent,
    output reg        busy,
    output reg        done
);
    // block length is fixed at 8 words
    initial remaining = 4'd8;
    initial sent      = 4'd0;
    initial busy      = 1'b1;
    initial done      = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            remaining <= 4'd8;
            sent      <= 4'd0;
            busy      <= 1'b1;
            done      <= 1'b0;
        end else if (ce) begin
            if (remaining != 4'd0) begin
                remaining <= remaining - 4'd1;
                sent      <= sent + 4'd1;
                if (remaining == 4'd1)
                    busy <= 1'b0;
            end
            // done is raised the cycle after the last word retires
            done <= (remaining == 4'd0);
        end
    end

    // P: the engine must never report completion while still claiming to copy
    always @(posedge clk)
        if (done)
            assert (!busy);
endmodule

module prio_pipe (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    input  wire [7:0] req,
    output reg        y_valid,
    output reg  [2:0] y_index,
    output reg        y_bit
);
    // combinational priority encode of the incoming request vector
    wire       c_valid = |req;
    wire [2:0] c_index = req[7] ? 3'd7 :
                         req[6] ? 3'd6 :
                         req[5] ? 3'd5 :
                         req[4] ? 3'd4 :
                         req[3] ? 3'd3 :
                         req[2] ? 3'd2 :
                         req[1] ? 3'd1 : 3'd0;

    // stage 1: captured request vector plus its encoding
    reg [7:0] q_req;
    reg       q_valid;
    reg [2:0] q_index;

    initial begin
        q_req   = 8'h00;
        q_valid = 1'b0;
        q_index = 3'd0;
        y_valid = 1'b0;
        y_index = 3'd0;
        y_bit   = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            q_req   <= 8'h00;
            q_valid <= 1'b0;
            q_index <= 3'd0;
        end else if (i_ce) begin
            q_req   <= req;
            q_valid <= c_valid;
            q_index <= c_index;
        end
    end

    // stage 2: registered output stage, samples the selected bit out of the
    // captured vector using the captured index
    always @(posedge clk) begin
        if (rst) begin
            y_valid <= 1'b0;
            y_index <= 3'd0;
            y_bit   <= 1'b0;
        end else if (i_ce) begin
            y_valid <= q_valid;
            y_index <= q_index;
            y_bit   <= q_req[q_index];
        end
    end

    // property: a granted output must point at a bit that was actually set
    always @(posedge clk)
        if (y_valid)
            assert (y_bit == 1'b1);
endmodule

// Two-road intersection controller.
// Light codes: 0 = RED, 1 = GREEN, 2 = YELLOW
// Phases: 0 NS-green, 1 NS-yellow, 2 all-red, 3 EW-green, 4 EW-yellow, 5 all-red
// Each phase handover advances the affected road's light one step around the
// RED -> GREEN -> YELLOW -> RED ring.
module intersection_ctrl (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    output wire       o_ns_green,
    output wire       o_ew_green,
    output wire [2:0] o_phase
);
    localparam [1:0] RED    = 2'd0;
    localparam [1:0] GREEN  = 2'd1;
    localparam [1:0] YELLOW = 2'd2;

    localparam [2:0] PHASE_LEN = 3'd4;

    reg [2:0] phase;
    reg [2:0] timer;
    reg [1:0] ns_state;
    reg [1:0] ew_state;

    initial phase    = 3'd0;
    initial timer    = PHASE_LEN;
    initial ns_state = GREEN;
    initial ew_state = RED;

    // one step around the three-colour ring
    function [1:0] nextcolor;
        input [1:0] c;
        begin
            if (c == YELLOW)
                nextcolor = RED;
            else
                nextcolor = c + 2'd1;
        end
    endfunction

    always @(posedge clk) begin
        if (rst) begin
            phase    <= 3'd0;
            timer    <= PHASE_LEN;
            ns_state <= GREEN;
            ew_state <= RED;
        end else if (ce) begin
            if (timer != 3'd0) begin
                timer <= timer - 3'd1;
            end else begin
                timer <= PHASE_LEN;
                case (phase)
                3'd0: begin // NS green expires -> NS yellow
                    phase    <= 3'd1;
                    ns_state <= nextcolor(ns_state);
                end
                3'd1: begin // NS yellow expires -> all red
                    phase    <= 3'd2;
                    ns_state <= nextcolor(ns_state);
                end
                3'd2: begin // all red -> EW green
                    phase    <= 3'd3;
                    ew_state <= nextcolor(ew_state);
                end
                3'd3: begin // EW green expires -> EW yellow
                    phase    <= 3'd4;
                    ew_state <= nextcolor(ew_state);
                end
                3'd4: begin // EW yellow expires -> all red
                    phase    <= 3'd5;
                    ew_state <= nextcolor(ew_state);
                end
                3'd5: begin // all red -> NS green
                    phase    <= 3'd0;
                    ns_state <= nextcolor(ns_state);
                end
                default: begin
                    phase <= phase;
                end
                endcase
            end
        end
    end

    assign o_ns_green = (ns_state == GREEN);
    assign o_ew_green = (ew_state == GREEN);
    assign o_phase    = phase;

    // P: the two roads are never green at the same time
    always @(*)
        if (ns_state == GREEN)
            assert (ew_state != GREEN);
endmodule

module pwm_dimmer_seq (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [7:0] duty_in,
    output wire       pwm
);
    // free-running PWM phase counter
    reg [3:0] phase       = 4'd0;
    // rotating one-hot channel selector, advanced once per PWM period
    reg [3:0] chan_sel    = 4'b0001;
    // binary mirror of the selector position
    reg [1:0] idx         = 2'd0;
    // duty latched at the period boundary
    reg [7:0] duty_shadow = 8'd0;

    assign pwm = (phase < duty_shadow[7:4]);

    wire period_end = ce && (phase == 4'd15);

    always @(posedge clk) begin
        if (rst) begin
            phase       <= 4'd0;
            chan_sel    <= 4'b0001;
            idx         <= 2'd0;
            duty_shadow <= 8'd0;
        end else if (ce) begin
            phase <= phase + 4'd1;
            if (phase == 4'd15) begin
                chan_sel    <= {chan_sel[2:0], chan_sel[3]};
                idx         <= idx + 2'd1;
                duty_shadow <= duty_in;
            end
        end
    end

    // P: when the mirror index points at position 0, the one-hot selector
    //    must be sitting on channel 0.
    always @(posedge clk)
        if (idx == 2'd0)
            assert (chan_sel == 4'b0001);
endmodule

module minmax_abs_track (
    input wire i_clk,
    input wire i_rst,
    input wire i_ce,
    input wire i_push,
    input wire signed [7:0] i_val,
    output wire [7:0] o_min,
    output wire [7:0] o_max,
    output wire [3:0] o_count,
    output wire o_bad
);
    // Tracks the running min and max of the magnitudes (absolute values) of a
    // stream of signed samples, plus a saturating sample counter and a latched
    // order-violation flag.

    reg [7:0] mn;
    reg [7:0] mx;
    reg       valid;
    reg [3:0] count;
    reg       bad;

    initial mn    = 8'hff;
    initial mx    = 8'h00;
    initial valid = 1'b0;
    initial count = 4'd0;
    initial bad   = 1'b0;

    // unsigned magnitude of the signed input (|-128| == 8'h80 fits unsigned)
    wire [7:0] mag = i_val[7] ? (~i_val + 8'd1) : i_val;

    always @(posedge i_clk) begin
        if (i_rst) begin
            mn    <= 8'hff;
            mx    <= 8'h00;
            valid <= 1'b0;
            count <= 4'd0;
            bad   <= 1'b0;
        end else if (i_ce) begin
            // order checker: samples the registered extremes, gated by the
            // *counter* rather than by the valid flag
            bad <= (count != 4'd0) && (mn > mx);

            if (i_push) begin
                if (!valid) begin
                    mn <= mag;
                    mx <= mag;
                end else begin
                    if (mag < mn)
                        mn <= mag;
                    if (mag > mx)
                        mx <= mag;
                end
                valid <= 1'b1;
                count <= (count == 4'd15) ? 4'd15 : (count + 4'd1);
            end
        end
    end

    assign o_min   = mn;
    assign o_max   = mx;
    assign o_count = count;
    assign o_bad   = bad;

    // Property: once at least one sample has been absorbed, the order checker
    // must never have fired.
    always @(posedge i_clk)
        if (valid)
            assert (!bad);

endmodule

module chess_clock (
    input  wire       clk,
    input  wire       rst,
    input  wire       tick,   // enable: when low, all state is held
    input  wire       press,  // toggles which side is running
    output reg  [5:0] w_time,
    output reg  [5:0] b_time,
    output reg  [5:0] elapsed,
    output reg        turn
);
    localparam [5:0] BUDGET = 6'd16;

    // clock is frozen once either side has run out
    wire frozen = (w_time == 6'd0) || (b_time == 6'd0);

    initial w_time  = BUDGET;
    initial b_time  = BUDGET;
    initial elapsed = 6'd0;
    initial turn    = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            w_time  <= BUDGET;
            b_time  <= BUDGET;
            elapsed <= 6'd0;
            turn    <= 1'b0;
        end else if (tick && !frozen) begin
            if (turn == 1'b0)
                w_time <= w_time - 6'd1;
            else
                b_time <= b_time - 6'd1;

            elapsed <= elapsed + 6'd1;

            if (press)
                turn <= ~turn;
        end
    end

    // P: while the clock is still running, at most BUDGET*2-2 ticks can have elapsed
    always @(posedge clk)
        if (!frozen)
            assert (elapsed <= 6'd30);
endmodule

module nano_alu_flags (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [1:0] op,      // 00=ADD 01=SUB 10=AND 11=PASS/refresh
    input wire [7:0] b,
    output reg [7:0] acc,
    output reg zf,            // zero flag
    output reg nf,            // negative (sign) flag
    output reg cf             // carry flag
);

    initial begin
        acc = 8'h00;
        zf  = 1'b1;           // acc == 0 at start
        nf  = 1'b0;
        cf  = 1'b0;
    end

    wire [8:0] add_res = {1'b0, acc} + {1'b0, b};
    wire [8:0] sub_res = {1'b0, acc} - {1'b0, b};
    wire [7:0] and_res = acc & b;

    reg [7:0] res;
    reg        carry;

    always @(*) begin
        case (op)
            2'b00: begin res = add_res[7:0]; carry = add_res[8]; end
            2'b01: begin res = sub_res[7:0]; carry = sub_res[8]; end
            2'b10: begin res = and_res;      carry = 1'b0;       end
            default: begin res = acc;        carry = cf;         end // PASS
        endcase
    end

    always @(posedge clk) begin
        if (rst) begin
            acc <= 8'h00;
            zf  <= 1'b1;
            nf  <= 1'b0;
            cf  <= 1'b0;
        end else if (ce) begin
            acc <= res;
            zf  <= (res == 8'h00);
            cf  <= carry;
            // sign flag is only rewritten by ops that actually change acc
            if (op != 2'b11)
                nf <= res[7];
        end
    end

    // P: the zero flag and the negative flag are never both asserted
    always @(posedge clk)
        if (zf)
            assert (!nf);

endmodule

module str_reverse_stack (
    input wire clk,
    input wire rst,
    input wire push,
    input wire pop,
    input wire [7:0] in_char,
    output reg [7:0] out_char
);
    // Character stack used to reverse a string: chars are pushed in order and
    // popped out back-to-front.  n_pushed / n_popped are free-running mod-16
    // bookkeeping counters of how many characters entered and left the stack.
    reg [3:0] sp       = 4'd0;
    reg [3:0] n_pushed = 4'd0;
    reg [3:0] n_popped = 4'd0;
    reg [7:0] mem [0:7];

    integer i;
    initial begin
        out_char = 8'h00;
        for (i = 0; i < 8; i = i + 1) mem[i] = 8'h00;
    end

    wire full    = (sp >= 4'd8);
    wire empty   = (sp == 4'd0);
    wire do_push = push && !full;
    wire do_pop  = !do_push && pop && !empty;

    always @(posedge clk) begin
        if (rst) begin
            sp       <= 4'd0;
            n_pushed <= 4'd0;
            n_popped <= 4'd0;
            out_char <= 8'h00;
        end else if (do_push) begin
            mem[sp[2:0]] <= in_char;
            sp           <= sp + 4'd1;
            n_pushed     <= n_pushed + 4'd1;
        end else if (do_pop) begin
            out_char <= mem[sp[2:0] - 3'd1];
            sp       <= sp - 4'd1;
            n_popped <= n_popped + 4'd1;
        end
    end

    // P: whenever the character stack is empty, exactly as many characters have
    // left it as entered it.
    always @(posedge clk)
        if (sp == 4'd0)
            assert (n_pushed == n_popped);
endmodule

module token_bucket (
    input wire clk,
    input wire rst,
    input wire drip,
    input wire spend,
    output reg [2:0] tokens,
output reg tokens_hi,
output reg [3:0] spent_total
);
    wire drip_en  = drip  && (tokens != 3'd4);
    wire spend_en = spend && (tokens != 3'd0);
    wire inc = drip_en && !spend_en;
    wire dec = spend_en && !drip_en;

    initial tokens   = 3'd0;
    initial tokens_hi = 1'b0;
    initial spent_total = 4'd0;

    always @(posedge clk) begin
        if (rst) begin
            tokens    <= 3'd0;
            tokens_hi <= 1'b0;
            spent_total <= 4'd0;
        end else begin
            if (dec) spent_total <= spent_total + 4'd1;
            if (inc)      tokens <= tokens + 3'd1;
            else if (dec) tokens <= tokens - 3'd1;

            if (inc && tokens == 3'd1)      tokens_hi <= 1'b1;
            else if (dec && tokens == 3'd2) tokens_hi <= 1'b0;
        end
    end

    always @(posedge clk)
        if (tokens_hi) assert (tokens != 3'd0);
endmodule

module token_bucket (
    input wire clk,
    input wire rst,
    input wire drip,
    input wire spend,
    output reg [2:0] tokens,
output reg tokens_hi,
output reg [3:0] drip_count
);
    wire drip_en  = drip  && (tokens != 3'd4);
    wire spend_en = spend && (tokens != 3'd0);
    wire inc = drip_en && !spend_en;
    wire dec = spend_en && !drip_en;

    initial tokens   = 3'd0;
    initial tokens_hi = 1'b0;
initial drip_count = 4'd0;

    always @(posedge clk) begin
        if (rst) begin
            tokens    <= 3'd0;
            tokens_hi <= 1'b0;
drip_count <= 4'd0;
        end else begin
            if (inc)      tokens <= tokens + 3'd1;
            else if (dec) tokens <= tokens - 3'd1;

            if (inc && tokens == 3'd1)      tokens_hi <= 1'b1;
            else if (dec && tokens == 3'd2) tokens_hi <= 1'b0;
if (drip_en && drip_count != 4'd15) drip_count <= drip_count + 4'd1;
        end
    end

    always @(posedge clk)
        if (tokens_hi) assert (tokens != 3'd0);
endmodule

module token_bucket (
    input wire clk,
    input wire rst,
    input wire drip,
    input wire spend,
    output reg [2:0] tokens,
    output reg tokens_hi
);
    reg deep;  // registered level>=3 flag, re-evaluated when the level moves
    wire drip_en  = drip  && (tokens != 3'd4);
    wire spend_en = spend && (tokens != 3'd0);
    wire inc = drip_en && !spend_en;
    wire dec = spend_en && !drip_en;

    // burst drain: while the bucket is deep a spend sheds two tokens at once
    wire bulk = dec && deep;
    wire lite = dec && !deep;
    wire [2:0] nxt = inc  ? tokens + 3'd1 :
                     bulk ? tokens - 3'd2 :
                     lite ? tokens - 3'd1 : tokens;

    initial tokens   = 3'd0;
    initial tokens_hi = 1'b0;
    initial deep = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            tokens    <= 3'd0;
            tokens_hi <= 1'b0;
            deep      <= 1'b0;
        end else begin
            tokens <= nxt;
            if (inc || dec) deep <= (nxt >= 3'd3);

            if (inc && tokens == 3'd1)       tokens_hi <= 1'b1;
            else if (lite && tokens == 3'd2) tokens_hi <= 1'b0;
            else if (bulk && tokens == 3'd3) tokens_hi <= 1'b0;
        end
    end

    always @(posedge clk)
        if (tokens_hi) assert (tokens != 3'd0);
endmodule

module token_bucket (
    input wire clk,
    input wire rst,
    input wire drip,
    input wire spend,
    output reg [2:0] tokens,
    output reg tokens_hi
);
    reg pace;   // refill divider: only every other drip request is honoured
    wire drip_ok  = drip && !pace;
    wire drip_en  = drip_ok && (tokens != 3'd4);
    wire spend_en = spend && (tokens != 3'd0);
    wire inc = drip_en && !spend_en;
    wire dec = spend_en && !drip_en;

    initial tokens   = 3'd0;
    initial tokens_hi = 1'b0;
    initial pace      = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            tokens    <= 3'd0;
            tokens_hi <= 1'b0;
            pace      <= 1'b0;
        end else begin
            if (drip) pace <= !pace;

            if (inc)      tokens <= tokens + 3'd1;
            else if (dec) tokens <= tokens - 3'd1;

            if (inc && tokens == 3'd1)      tokens_hi <= 1'b1;
            else if (dec && tokens == 3'd2) tokens_hi <= 1'b0;
        end
    end

    always @(posedge clk)
        if (tokens_hi) assert (tokens != 3'd0);

    always @(posedge clk)
        if (tokens == 3'd4) assert (tokens_hi);
endmodule

module pwm_dimmer (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [7:0] duty_in,
    output wire pwm_out
);
    reg [7:0] cnt      = 8'd0;   // free-running ramp
    reg [7:0] duty_reg = 8'd0;   // duty latched at period start
    reg [7:0] high_cnt = 8'd0;   // high-time accumulated this period

    always @(posedge clk)
        if (rst) begin
            cnt      <= 8'd0;
            duty_reg <= 8'd0;
            high_cnt <= 8'd0;
        end else if (ce) begin
            if (cnt == 8'd0) begin
                duty_reg <= duty_in;
                high_cnt <= (duty_in != 8'd0) ? 8'd1 : 8'd0;
                cnt      <= 8'd1;
            end else if (cnt == 8'hFF) begin
                cnt      <= 8'd0;
                high_cnt <= 8'd0;
            end else begin
                cnt      <= cnt + 8'd1;
                high_cnt <= high_cnt + ((cnt < duty_reg) ? 8'd1 : 8'd0);
            end
        end

    assign pwm_out = (cnt < duty_reg);

    always @(posedge clk)
        if (pwm_out)
            assert (high_cnt < duty_reg);

   // Duty accounting check: once the pulse for this period has ended,
   // the accumulated high time must equal the programmed duty exactly,
   // otherwise the average brightness would drift from the setpoint.
   always @(posedge clk)
       if (!pwm_out)
           assert (high_cnt == duty_reg);
endmodule

module watchdog (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire kick,
    input wire ack,
    output reg fault
);
    reg [3:0] timer;
    reg [3:0] elapsed;
reg [3:0] period;
wire [3:0] period_tight = (period == 4'd4) ? 4'd4 : period - 4'd1;
wire [3:0] period_relax = (period == 4'd8) ? 4'd8 : period + 4'd1;
initial begin timer = 4'd8; elapsed = 4'd0; fault = 1'b0; period = 4'd8; end

    always @(posedge clk) begin
        if (rst) begin
            timer   <= 4'd8;
            elapsed <= 4'd0;
            fault   <= 1'b0;
period  <= 4'd8;
        end else if (i_ce) begin
            if (ack) begin
timer   <= period_tight;
period  <= period_tight;
                elapsed <= 4'd0;
                fault   <= 1'b0;
            end else if (kick && !fault) begin
timer   <= period_relax;
period  <= period_relax;
                elapsed <= 4'd0;
            end else begin
                if (timer != 4'd0)   timer   <= timer - 4'd1;
if (elapsed != period) elapsed <= elapsed + 4'd1;
                if (timer == 4'd1)   fault   <= 1'b1;
            end
        end
    end

    always @(posedge clk)
        if (elapsed == 4'd8)
            assert (fault);
endmodule

module stack_hwm (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire push,
    input wire pop,
    input wire [7:0] din,
    output wire [7:0] top
);
    reg [3:0] sp;
    reg [3:0] hwm;
    reg [7:0] mem [0:15];
    reg        wb_v;
    reg [7:0]  wb_d;
    initial begin sp = 4'd0; hwm = 4'd0; wb_v = 1'b0; wb_d = 8'h00; end

    wire [3:0] occ = sp + {3'b000, wb_v};
    wire do_push = ce && push && (occ != 4'd8);
    wire do_pop  = ce && pop  && (occ != 4'd0);
    wire [3:0] nxt = occ + 4'd1;

    assign top = wb_v ? wb_d : ((sp == 4'd0) ? 8'h00 : mem[sp - 4'd1]);

    always @(posedge clk) begin
        if (rst) begin
            sp  <= 4'd0;
            hwm <= 4'd0;
            wb_v <= 1'b0;
            wb_d <= 8'h00;
        end else begin
            case ({do_push, do_pop})
                2'b10: begin
                    if (wb_v) begin
                        mem[sp] <= wb_d;
                        sp <= sp + 4'd1;
                    end
                    wb_v <= 1'b1;
                    wb_d <= din;
                    if (nxt > hwm) hwm <= nxt;
                end
                2'b01: begin
                    if (wb_v) wb_v <= 1'b0;
                    else      sp   <= sp - 4'd1;
                end
                default: if (ce && wb_v) begin
                    mem[sp] <= wb_d;
                    sp      <= sp + 4'd1;
                    wb_v    <= 1'b0;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (sp == 4'd8)
            assert (hwm == 4'd8);
endmodule

module stack_hwm (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire push,
    input wire pop,
    input wire [7:0] din,
    output wire [7:0] top
);
    reg [3:0] sp;
    reg [3:0] hwm;
reg [3:0] hdrm;
    reg [7:0] mem [0:15];
initial begin sp = 4'd0; hwm = 4'd0; hdrm = 4'd8; end

    wire do_push = ce && push && (sp != 4'd8);
    wire do_pop  = ce && pop  && (sp != 4'd0);
    wire [3:0] nxt = sp + 4'd1;

// an empty stack reads back the depth status: {high-water mark, headroom}
wire [7:0] status = {hwm, hdrm};


assign top = (sp == 4'd0) ? status : mem[sp - 4'd1];

    always @(posedge clk) begin
        if (rst) begin
            sp  <= 4'd0;
            hwm <= 4'd0;
hdrm <= 4'd8;
        end else begin
            case ({do_push, do_pop})
                2'b10: begin
                    mem[sp] <= din;
                    sp <= nxt;
if (nxt > hwm) begin
    hwm <= nxt;
    // headroom shrinks with every new peak and saturates at the limit
    if (hdrm != 4'd0) hdrm <= hdrm - 4'd1;
end
                end
                2'b01: sp <= sp - 4'd1;
                default: ;
            endcase
        end
    end

    always @(posedge clk)
        if (sp == 4'd8)
            assert (hwm == 4'd8);

always @(posedge clk)
    assert ({1'b0, hwm} + {1'b0, hdrm} == 5'd8);
endmodule

module rr_arbiter_pri (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    input  wire [3:0] req,
    output wire [3:0] gnt,
    output reg  [3:0] pri,
    output reg  [1:0] idx
);
    initial pri = 4'b0001;
    initial idx = 2'd0;

   // second request port; both ports share the one grant bus via a token
   reg  [3:0] pri_b;   // port B's rotating priority pointer
   reg  [1:0] off;     // slots B's pointer sits ahead of the shared index
   reg        own;     // 0: port A drives gnt, 1: port B drives gnt
   initial pri_b = 4'b0001;
   initial off   = 2'd0;
   initial own   = 1'b0;

    // only the requester currently pointed at by the rotating priority wins
   wire [3:0] cur_pri = own ? pri_b : pri;
   assign gnt = req & cur_pri;

    wire low_pri = pri[0] | pri[1];   // priority pointer sits in lower half
    wire idx_hi  = idx[1];            // binary index says upper half

   // an owner that cannot place a grant this cycle releases the shared bus
   wire pass = ~|gnt;

    always @(posedge clk) begin
        if (rst) begin
            pri <= 4'b0001;
            idx <= 2'd0;
           pri_b <= 4'b0001;
           off   <= 2'd0;
           own   <= 1'b0;
        end else if (step) begin
           if (pass) begin
               own <= ~own;
               if (own) begin
                   // B releases: A resumes the scan where B stopped
                   pri <= pri_b;
                   idx <= idx + off;
                   off <= 2'd0;
               end else begin
                   // A releases: B picks the scan up at A's pointer
                   pri_b <= pri;
                   off   <= 2'd0;
               end
           end else if (own) begin
               // B holds the bus: only B's pointer walks, it pulls ahead
               pri_b <= {pri_b[2:0], pri_b[3]};
               off   <= off + 2'd1;
           end else begin
               // A holds the bus: A walks, closing on B's parked pointer
               pri <= {pri[2:0], pri[3]};
               idx <= idx + 2'd1;
               off <= off - 2'd1;
           end
        end
    end

    always @(posedge clk)
        if (|gnt)
            assert (!(low_pri && idx_hi));
endmodule

module rr_arbiter_pri (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    input  wire [3:0] req,
    output wire [3:0] gnt,
    output reg  [3:0] pri,
    output reg  [1:0] idx
);
    initial pri = 4'b0001;
    initial idx = 2'd0;

   reg [1:0] hold_cnt;   // cycles left in the current grant burst
   initial hold_cnt = 2'd0;

    // only the requester currently pointed at by the rotating priority wins
    assign gnt = req & pri;

    wire low_pri = pri[0] | pri[1];   // priority pointer sits in lower half
    wire idx_hi  = idx[1];            // binary index says upper half

   wire hold_active  = (hold_cnt != 2'd0);
   // a fresh grant opens a burst; the pointer moves on the last burst cycle,
   // or right away when the requester it points at has nothing pending
   wire burst_start  = (|gnt) && !hold_active;
   wire rotate       = step && ((hold_cnt == 2'd1) || (!hold_active && !(|gnt)));

    always @(posedge clk) begin
        if (rst) begin
            pri <= 4'b0001;
            idx <= 2'd0;
           hold_cnt <= 2'd0;
       end else begin
           if (rotate) begin
               pri <= {pri[2:0], pri[3]};
               idx <= idx + 2'd1;
           end
           if (burst_start)
               hold_cnt <= 2'd3;
           else if (step && hold_active)
               hold_cnt <= hold_cnt - 2'd1;
       end
    end

    always @(posedge clk)
        if (|gnt)
            assert (!(low_pri && idx_hi));

   // the binary index must always name the requester that is being granted
   always @(posedge clk)
       if (|gnt)
           assert (gnt[idx]);
endmodule

module pwm_dimmer (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [7:0] duty_in,
    output wire pwm_out
);
    reg [7:0] cnt      = 8'd0;   // free-running ramp
    reg [7:0] duty_reg = 8'd0;   // duty latched at period start
    reg [7:0] high_cnt = 8'd0;   // high-time accumulated this period
    reg       hi_q     = 1'b0;   // compare result, registered ahead of the accumulator
    reg [7:0] duty_cap = 8'd0;   // duty request captured at ramp end, after foldback clamp

    localparam [7:0] HI_LIMIT = 8'd192; // high cycles per period allowed by thermal budget

    always @(posedge clk)
        if (rst) begin
            cnt      <= 8'd0;
            duty_reg <= 8'd0;
            high_cnt <= 8'd0;
            hi_q     <= 1'b0;
            duty_cap <= 8'd0;
        end else if (ce) begin
            if (cnt == 8'd0) begin
                duty_reg <= duty_cap;
                high_cnt <= 8'd0;
                hi_q     <= (duty_cap != 8'd0);
                cnt      <= 8'd1;
            end else if (cnt == 8'hFF) begin
                duty_cap <= (high_cnt >= HI_LIMIT) ? HI_LIMIT : duty_in;
                cnt      <= 8'd0;
                high_cnt <= 8'd0;
                hi_q     <= 1'b0;
            end else begin
                cnt      <= cnt + 8'd1;
                high_cnt <= high_cnt + {7'd0, hi_q};
                hi_q     <= (cnt < duty_reg);
            end
        end

    assign pwm_out = (cnt < duty_reg);

    always @(posedge clk)
        if (pwm_out)
            assert (high_cnt < duty_reg);
endmodule

module token_bucket (
    input wire clk,
    input wire rst,
    input wire drip,
    input wire spend,
    output reg [2:0] tokens,
    output reg tokens_hi
);
    wire drip_en  = drip  && (tokens != 3'd4);
    wire spend_en = spend && (tokens != 3'd0);
    wire inc = drip_en && !spend_en;
    wire dec = spend_en && !drip_en;

    initial tokens   = 3'd0;
    initial tokens_hi = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            tokens    <= 3'd0;
            tokens_hi <= 1'b0;
        end else begin
            if (inc)      tokens <= tokens + 3'd1;
            else if (dec) tokens <= tokens - 3'd1;

            if (inc && tokens == 3'd1)      tokens_hi <= 1'b1;
            else if (dec && tokens == 3'd2) tokens_hi <= 1'b0;
        end
    end

    always @(posedge clk)
        if (tokens_hi) assert (tokens != 3'd0);
endmodule

module token_bucket_pool (
    input  wire       clk,
    input  wire       rst,
    input  wire [5:0] drip_req,
    input  wire [5:0] spend_req,
    output reg  [3:0] pool,
    output wire [5:0] hi_flags,
    output reg        starved
);
    localparam [3:0] TOTAL = 4'd8;

    // per-instance observable state
    wire [2:0] t0, t1, t2, t3, t4, t5;
    wire       h0, h1, h2, h3, h4, h5;

    // a bucket wants a credit only if the drip would really land:
    // not already full, and not cancelled by a concurrent accepted spend
    wire [5:0] want;
    assign want[0] = drip_req[0] && (t0 != 3'd4) && !(spend_req[0] && (t0 != 3'd0));
    assign want[1] = drip_req[1] && (t1 != 3'd4) && !(spend_req[1] && (t1 != 3'd0));
    assign want[2] = drip_req[2] && (t2 != 3'd4) && !(spend_req[2] && (t2 != 3'd0));
    assign want[3] = drip_req[3] && (t3 != 3'd4) && !(spend_req[3] && (t3 != 3'd0));
    assign want[4] = drip_req[4] && (t4 != 3'd4) && !(spend_req[4] && (t4 != 3'd0));
    assign want[5] = drip_req[5] && (t5 != 3'd4) && !(spend_req[5] && (t5 != 3'd0));

    wire credit_avail = (pool != 4'd0);

    // one credit per cycle, fixed priority
    wire [5:0] grant;
    assign grant[0] = credit_avail && want[0];
    assign grant[1] = credit_avail && want[1] && !want[0];
    assign grant[2] = credit_avail && want[2] && !want[0] && !want[1];
    assign grant[3] = credit_avail && want[3] && !want[0] && !want[1] && !want[2];
    assign grant[4] = credit_avail && want[4] && !want[0] && !want[1] && !want[2] && !want[3];
    assign grant[5] = credit_avail && want[5] && !want[0] && !want[1] && !want[2] && !want[3] && !want[4];
    wire grant_any = grant[0] || grant[1] || grant[2] || grant[3] || grant[4] || grant[5];

    // a released token returns its credit
    wire [5:0] rel;
    assign rel[0] = spend_req[0] && (t0 != 3'd0) && !(grant[0] && (t0 != 3'd4));
    assign rel[1] = spend_req[1] && (t1 != 3'd0) && !(grant[1] && (t1 != 3'd4));
    assign rel[2] = spend_req[2] && (t2 != 3'd0) && !(grant[2] && (t2 != 3'd4));
    assign rel[3] = spend_req[3] && (t3 != 3'd0) && !(grant[3] && (t3 != 3'd4));
    assign rel[4] = spend_req[4] && (t4 != 3'd0) && !(grant[4] && (t4 != 3'd4));
    assign rel[5] = spend_req[5] && (t5 != 3'd0) && !(grant[5] && (t5 != 3'd4));

    wire [3:0] rel_cnt = {3'd0, rel[0]} + {3'd0, rel[1]} + {3'd0, rel[2]} +
                         {3'd0, rel[3]} + {3'd0, rel[4]} + {3'd0, rel[5]};

    token_bucket u0 (.clk(clk), .rst(rst), .drip(grant[0]), .spend(spend_req[0]), .tokens(t0), .tokens_hi(h0));
    token_bucket u1 (.clk(clk), .rst(rst), .drip(grant[1]), .spend(spend_req[1]), .tokens(t1), .tokens_hi(h1));
    token_bucket u2 (.clk(clk), .rst(rst), .drip(grant[2]), .spend(spend_req[2]), .tokens(t2), .tokens_hi(h2));
    token_bucket u3 (.clk(clk), .rst(rst), .drip(grant[3]), .spend(spend_req[3]), .tokens(t3), .tokens_hi(h3));
    token_bucket u4 (.clk(clk), .rst(rst), .drip(grant[4]), .spend(spend_req[4]), .tokens(t4), .tokens_hi(h4));
    token_bucket u5 (.clk(clk), .rst(rst), .drip(grant[5]), .spend(spend_req[5]), .tokens(t5), .tokens_hi(h5));

    assign hi_flags = {h5, h4, h3, h2, h1, h0};

    initial pool    = TOTAL;
    initial starved = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            pool    <= TOTAL;
            starved <= 1'b0;
        end else begin
            pool <= pool + rel_cnt - {3'd0, grant_any};
            if (pool == 4'd0) starved <= 1'b1;
        end
    end

    // when the pool is exhausted all credits sit in the buckets, so at least
    // one bucket must be above its high-water mark
    always @(posedge clk)
        if (pool == 4'd0)
            assert (h0 || h1 || h2 || h3 || h4 || h5);
endmodule

module pwm_dimmer (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [7:0] duty_in,
    output wire pwm_out
);
    reg [7:0] cnt      = 8'd0;   // free-running ramp
    reg [7:0] duty_reg = 8'd0;   // duty latched at period start
    reg [7:0] high_cnt = 8'd0;   // high-time accumulated this period

   // compare -> accumulate path registered four deep to meet timing at the
   // top clock rate; each stage carries one pending high-time increment and
   // the last stage is the PWM output itself, so output and accumulator stay
   // aligned by construction.
   reg inc_s0 = 1'b0;
   reg inc_s1 = 1'b0;
   reg inc_s2 = 1'b0;
   reg inc_s3 = 1'b0;

    always @(posedge clk)
        if (rst) begin
            cnt      <= 8'd0;
            duty_reg <= 8'd0;
            high_cnt <= 8'd0;
           inc_s0   <= 1'b0;
           inc_s1   <= 1'b0;
           inc_s2   <= 1'b0;
           inc_s3   <= 1'b0;
        end else if (ce) begin
            if (cnt == 8'd0) begin
                duty_reg <= duty_in;
               high_cnt <= 8'd0;
               inc_s0   <= (duty_in != 8'd0);
               inc_s1   <= inc_s0;
               inc_s2   <= inc_s1;
               inc_s3   <= inc_s2;
                cnt      <= 8'd1;
            end else if (cnt == 8'hFF) begin
                cnt      <= 8'd0;
                high_cnt <= 8'd0;
               inc_s0   <= 1'b0;
               inc_s1   <= 1'b0;
               inc_s2   <= 1'b0;
               inc_s3   <= 1'b0;
            end else begin
                cnt      <= cnt + 8'd1;
               high_cnt <= high_cnt + (inc_s3 ? 8'd1 : 8'd0);
               inc_s0   <= (cnt < duty_reg);
               inc_s1   <= inc_s0;
               inc_s2   <= inc_s1;
               inc_s3   <= inc_s2;
            end
        end

   assign pwm_out = inc_s3;

    always @(posedge clk)
        if (pwm_out)
            assert (high_cnt < duty_reg);
endmodule

module token_bucket (
    input wire clk,
    input wire rst,
    input wire drip,
    input wire spend,
    output reg [2:0] tokens,
    output reg tokens_hi
);
    wire drip_en  = drip  && (tokens != 3'd4);
    wire spend_en = spend && (tokens != 3'd0);
    wire inc = drip_en && !spend_en;
    wire dec = spend_en && !drip_en;

    initial tokens   = 3'd0;
    initial tokens_hi = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            tokens    <= 3'd0;
            tokens_hi <= 1'b0;
        end else begin
            if (inc)      tokens <= tokens + 3'd1;
            else if (dec) tokens <= tokens - 3'd1;

            if (inc && tokens == 3'd1)      tokens_hi <= 1'b1;
            else if (dec && tokens == 3'd2) tokens_hi <= 1'b0;
        end
    end

    always @(posedge clk)
        if (tokens_hi) assert (tokens != 3'd0);
endmodule

module dma_copier (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [7:0] rd_data,
    output reg  [3:0] wr_addr,
    output reg  [3:0] remaining,
    output reg  [7:0] wr_data,
    output wire       done
);
    localparam [3:0] TOTAL = 4'd8;

    initial wr_addr   = 4'd0;
    initial remaining = TOTAL;
    initial wr_data   = 8'h00;

    assign done = (remaining == 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            wr_addr   <= 4'd0;
            remaining <= TOTAL;
            wr_data   <= 8'h00;
        end else if (ce && remaining != 4'd0) begin
            wr_addr   <= wr_addr + 4'd1;
            remaining <= remaining - 4'd1;
            wr_data   <= rd_data;
        end
    end

    // P: while the block copy is still in flight, the write pointer must stay
    // inside the destination block (0..7).
    always @(posedge clk)
        if (!done)
            assert (wr_addr <= 4'd7);
endmodule

// Top level: a token-bucket rate limiter feeds a burst queue which drives the
// DMA copier one beat at a time.  The queue holds a whole burst's worth of
// beats plus the source word latched when the burst was granted.
module bucket_dma_top (
    input  wire       clk,
    input  wire       rst,
    input  wire       drip,
    input  wire       run,
    input  wire [7:0] src_data,
    output wire [2:0] tokens,
    output wire       tokens_hi,
    output wire [3:0] wr_addr,
    output wire [3:0] remaining,
    output wire [7:0] wr_data,
    output wire       done,
    output reg  [2:0] pending
);
    reg [7:0] hold;

    initial pending = 3'd0;
    initial hold    = 8'h00;

    // One beat leaves the queue per enabled cycle; each beat also spends a
    // token out of the bucket.
    wire beat = run && (pending != 3'd0) && (remaining != 4'd0);

    // A fresh burst is granted only when the bucket is above its low-water
    // mark, the queue has drained, and the block copy is still in flight.
    wire load = tokens_hi && (pending == 3'd0) && (remaining != 4'd0);

    // Grant no more beats than either the bucket or the destination block can
    // support.
    wire [2:0] grant = (remaining < {1'b0, tokens}) ? remaining[2:0] : tokens;

    always @(posedge clk) begin
        if (rst) begin
            pending <= 3'd0;
            hold    <= 8'h00;
        end else if (load) begin
            pending <= grant;
            hold    <= src_data;
        end else if (beat) begin
            pending <= pending - 3'd1;
        end
    end

    token_bucket u_bucket (
        .clk       (clk),
        .rst       (rst),
        .drip      (drip),
        .spend     (beat),
        .tokens    (tokens),
        .tokens_hi (tokens_hi)
    );

    dma_copier u_dma (
        .clk       (clk),
        .rst       (rst),
        .ce        (beat),
        .rd_data   (hold),
        .wr_addr   (wr_addr),
        .remaining (remaining),
        .wr_data   (wr_data),
        .done      (done)
    );

    // Composed property: any beat still sitting in the burst queue must have
    // somewhere left to land in the destination block.
    always @(posedge clk)
        if (pending != 3'd0)
            assert (remaining != 4'd0);
endmodule

module thermo_hyst (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    output reg        heat_on,
    output reg [2:0]  on_events,
    output reg [2:0]  off_events
);
    localparam [5:0] T_LOW  = 6'd20;
    localparam [5:0] T_HIGH = 6'd40;

    reg [5:0] temp;

    initial begin
        temp       = 6'd30;
        heat_on    = 1'b0;
        on_events  = 3'd0;
        off_events = 3'd0;
    end

    // hysteresis decisions
    wire turn_on  = ce && !heat_on && (temp <= T_LOW);
    wire turn_off = ce &&  heat_on && (temp >= T_HIGH);

    always @(posedge clk) begin
        if (rst) begin
            temp       <= 6'd30;
            heat_on    <= 1'b0;
            on_events  <= 3'd0;
            off_events <= 3'd0;
        end else if (ce) begin
            if (turn_on) begin
                heat_on   <= 1'b1;
                on_events <= on_events + 3'd1;
            end else if (turn_off) begin
                heat_on    <= 1'b0;
                off_events <= off_events + 3'd1;
            end

            // plant: heater warms, ambient cools
            if (heat_on) begin
                if (temp != 6'd63) temp <= temp + 6'd1;
            end else begin
                if (temp != 6'd0)  temp <= temp - 6'd1;
            end
        end
    end

    // P: whenever the heater is commanded on, strictly more on-events than
    // off-events have been logged, so the two event counters cannot agree.
    always @(posedge clk)
        if (heat_on)
            assert (on_events != off_events);

endmodule

module thermo_farm (
    input  wire       clk,
    input  wire       rst,
    input  wire [3:0] ce_req,
    output reg  [3:0] pool,
    output wire [3:0] heat_on_o,
    output wire [3:0] held_o
);
    localparam [3:0] TOTAL = 4'd4;

    // per-instance observable signals
    wire       h0, h1, h2, h3;
    wire [2:0] on0, on1, on2, on3;
    wire [2:0] off0, off1, off2, off3;

    wire [3:0] heat_v = {h3, h2, h1, h0};

    // registered mirror of which instances currently hold a credit
    reg [3:0] held;

    wire t0 = held[0];
    wire t1 = held[1];
    wire t2 = held[2];
    wire t3 = held[3];

    initial begin
        pool = TOTAL;
        held = 4'd0;
    end

    // credit accounting: a rising heater takes a credit, a falling one returns it
    wire [3:0] acq = heat_v & ~held;
    wire [3:0] rel = ~heat_v & held;

    wire [2:0] n_acq = {2'b00, acq[0]} + {2'b00, acq[1]} +
                       {2'b00, acq[2]} + {2'b00, acq[3]};
    wire [2:0] n_rel = {2'b00, rel[0]} + {2'b00, rel[1]} +
                       {2'b00, rel[2]} + {2'b00, rel[3]};

    wire [3:0] pool_nxt = pool + {1'b0, n_rel} - {1'b0, n_acq};

    // only an idle heater needs a credit; one-hot priority grant
    wire [3:0] want = ce_req & ~heat_v;
    wire [3:0] gnt;
    assign gnt[0] = want[0];
    assign gnt[1] = want[1] & ~want[0];
    assign gnt[2] = want[2] & ~want[1] & ~want[0];
    assign gnt[3] = want[3] & ~want[2] & ~want[1] & ~want[0];

    wire avail = (pool_nxt != 4'd0);

    // running heaters keep their enable so they can release; idle ones need a grant
    wire [3:0] ce_gated = (ce_req & heat_v) | (gnt & {4{avail}});

    always @(posedge clk) begin
        if (rst) begin
            pool <= TOTAL;
            held <= 4'd0;
        end else begin
            pool <= pool_nxt;
            held <= heat_v;
        end
    end

    thermo_hyst u0 (
        .clk(clk), .rst(rst), .ce(ce_gated[0]),
        .heat_on(h0), .on_events(on0), .off_events(off0)
    );
    thermo_hyst u1 (
        .clk(clk), .rst(rst), .ce(ce_gated[1]),
        .heat_on(h1), .on_events(on1), .off_events(off1)
    );
    thermo_hyst u2 (
        .clk(clk), .rst(rst), .ce(ce_gated[2]),
        .heat_on(h2), .on_events(on2), .off_events(off2)
    );
    thermo_hyst u3 (
        .clk(clk), .rst(rst), .ce(ce_gated[3]),
        .heat_on(h3), .on_events(on3), .off_events(off3)
    );

    assign heat_on_o = heat_v;
    assign held_o    = held;

    // Pool property: a completely free budget means nobody is recorded as holding.
    always @(posedge clk)
        if (pool == 4'd4)
            assert (!t0 && !t1 && !t2 && !t3);

endmodule

module token_bucket (
    input wire clk,
    input wire rst,
    input wire drip,
    input wire spend,
    output reg [2:0] tokens,
    output reg tokens_hi
);
    wire drip_en  = drip  && (tokens != 3'd4);
    wire spend_en = spend && (tokens != 3'd0);
    wire inc = drip_en && !spend_en;
    wire dec = spend_en && !drip_en;

    initial tokens   = 3'd0;
    initial tokens_hi = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            tokens    <= 3'd0;
            tokens_hi <= 1'b0;
        end else begin
            if (inc)      tokens <= tokens + 3'd1;
            else if (dec) tokens <= tokens - 3'd1;

            if (inc && tokens == 3'd1)      tokens_hi <= 1'b1;
            else if (dec && tokens == 3'd2) tokens_hi <= 1'b0;
        end
    end

    always @(posedge clk)
        if (tokens_hi) assert (tokens != 3'd0);
endmodule

module token_bucket_pool (
    input  wire       clk,
    input  wire       rst,
    input  wire [5:0] drip_req,
    input  wire [5:0] spend_req,
    output reg  [3:0] pool,
    output wire [5:0] hi_flags,
    output reg        starved
);
    localparam [3:0] TOTAL = 4'd8;

    // per-instance observable state
    wire [2:0] t0, t1, t2, t3, t4, t5;
    wire       h0, h1, h2, h3, h4, h5;

    // a bucket wants a credit only if the drip would really land:
    // not already full, and not cancelled by a concurrent accepted spend
    wire [5:0] want;
    assign want[0] = drip_req[0] && (t0 != 3'd4) && !(spend_req[0] && (t0 != 3'd0));
    assign want[1] = drip_req[1] && (t1 != 3'd4) && !(spend_req[1] && (t1 != 3'd0));
    assign want[2] = drip_req[2] && (t2 != 3'd4) && !(spend_req[2] && (t2 != 3'd0));
    assign want[3] = drip_req[3] && (t3 != 3'd4) && !(spend_req[3] && (t3 != 3'd0));
    assign want[4] = drip_req[4] && (t4 != 3'd4) && !(spend_req[4] && (t4 != 3'd0));
    assign want[5] = drip_req[5] && (t5 != 3'd4) && !(spend_req[5] && (t5 != 3'd0));

    wire credit_avail = (pool != 4'd0);

    // one credit per cycle, fixed priority
    wire [5:0] grant;
    assign grant[0] = credit_avail && want[0];
    assign grant[1] = credit_avail && want[1] && !want[0];
    assign grant[2] = credit_avail && want[2] && !want[0] && !want[1];
    assign grant[3] = credit_avail && want[3] && !want[0] && !want[1] && !want[2];
    assign grant[4] = credit_avail && want[4] && !want[0] && !want[1] && !want[2] && !want[3];
    assign grant[5] = credit_avail && want[5] && !want[0] && !want[1] && !want[2] && !want[3] && !want[4];
    wire grant_any = grant[0] || grant[1] || grant[2] || grant[3] || grant[4] || grant[5];

    // a released token returns its credit
    wire [5:0] rel;
    assign rel[0] = spend_req[0] && (t0 != 3'd0) && !(grant[0] && (t0 != 3'd4));
    assign rel[1] = spend_req[1] && (t1 != 3'd0) && !(grant[1] && (t1 != 3'd4));
    assign rel[2] = spend_req[2] && (t2 != 3'd0) && !(grant[2] && (t2 != 3'd4));
    assign rel[3] = spend_req[3] && (t3 != 3'd0) && !(grant[3] && (t3 != 3'd4));
    assign rel[4] = spend_req[4] && (t4 != 3'd0) && !(grant[4] && (t4 != 3'd4));
    assign rel[5] = spend_req[5] && (t5 != 3'd0) && !(grant[5] && (t5 != 3'd4));

    wire [3:0] rel_cnt = {3'd0, rel[0]} + {3'd0, rel[1]} + {3'd0, rel[2]} +
                         {3'd0, rel[3]} + {3'd0, rel[4]} + {3'd0, rel[5]};

    token_bucket u0 (.clk(clk), .rst(rst), .drip(grant[0]), .spend(spend_req[0]), .tokens(t0), .tokens_hi(h0));
    token_bucket u1 (.clk(clk), .rst(rst), .drip(grant[1]), .spend(spend_req[1]), .tokens(t1), .tokens_hi(h1));
    token_bucket u2 (.clk(clk), .rst(rst), .drip(grant[2]), .spend(spend_req[2]), .tokens(t2), .tokens_hi(h2));
    token_bucket u3 (.clk(clk), .rst(rst), .drip(grant[3]), .spend(spend_req[3]), .tokens(t3), .tokens_hi(h3));
    token_bucket u4 (.clk(clk), .rst(rst), .drip(grant[4]), .spend(spend_req[4]), .tokens(t4), .tokens_hi(h4));
    token_bucket u5 (.clk(clk), .rst(rst), .drip(grant[5]), .spend(spend_req[5]), .tokens(t5), .tokens_hi(h5));

    assign hi_flags = {h5, h4, h3, h2, h1, h0};

    initial pool    = TOTAL;
    initial starved = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            pool    <= TOTAL;
            starved <= 1'b0;
        end else begin
            pool <= pool + rel_cnt - {3'd0, grant_any};
            if (pool == 4'd0) starved <= 1'b1;
        end
    end

    // when the pool is exhausted all credits sit in the buckets, so at least
    // one bucket must be above its high-water mark
    always @(posedge clk)
        if (pool == 4'd0)
            assert (h0 || h1 || h2 || h3 || h4 || h5);

   // with seven or more credits still in the pool at most one token is
   // outstanding, so no bucket can have reached its high-water mark
   always @(posedge clk)
       if (pool >= 4'd7)
           assert (hi_flags == 6'd0);
endmodule

module alu_budget (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire [7:0] i_step,
    output wire [7:0] o_acc,
    output wire o_zero,
    output wire o_full
);
    localparam [7:0] LIMIT = 8'd200;

    reg [7:0] acc;   // accumulated result
    reg [7:0] rem;   // headroom credited to the accumulator
    reg [7:0] acc_b; // secondary channel accumulation
    reg       turn;  // round-robin owner of the shared credit pool
    initial acc = 8'd0;
    initial rem = LIMIT;
    initial acc_b = 8'd0;
    initial turn = 1'b0;

    wire grant = i_ce && (rem >= i_step);

    always @(posedge clk)
        if (rst) begin
            acc <= 8'd0;
            rem <= LIMIT;
            acc_b <= 8'd0;
            turn <= 1'b0;
        end else if (grant) begin
            rem  <= rem - i_step;
            turn <= ~turn;
            if (turn) acc_b <= acc_b + i_step;
            else      acc   <= acc   + i_step;
        end

    assign o_acc  = acc;
    assign o_zero = (acc == 8'd0) && (acc_b == 8'd0);
    assign o_full = (rem == 8'd0);

    // P: a nonzero accumulation never exceeds its saturation bound
    always @(*)
        if (!o_zero) assert (acc <= LIMIT);
endmodule

// Two-road intersection controller.
// Light codes: 0 = RED, 1 = GREEN, 2 = YELLOW
// Phases: 0 NS-green, 1 NS-yellow, 2 all-red, 3 EW-green, 4 EW-yellow, 5 all-red
// Each phase handover advances the affected road's light one step around the
// RED -> GREEN -> YELLOW -> RED ring.
module intersection_ctrl (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    output wire       o_ns_green,
    output wire       o_ew_green,
    output wire [2:0] o_phase
);
    localparam [1:0] RED    = 2'd0;
    localparam [1:0] GREEN  = 2'd1;
    localparam [1:0] YELLOW = 2'd2;

    localparam [2:0] PHASE_LEN = 3'd4;
   // clearance (all-red) intervals are held longer than the coloured phases
   localparam [2:0] CLEAR_LEN = 3'd6;

    reg [2:0] phase;
    reg [2:0] timer;
    reg [1:0] ns_state;
    reg [1:0] ew_state;

    initial phase    = 3'd0;
    initial timer    = PHASE_LEN;
    initial ns_state = GREEN;
    initial ew_state = RED;

    // one step around the three-colour ring
    function [1:0] nextcolor;
        input [1:0] c;
        begin
            if (c == YELLOW)
                nextcolor = RED;
            else
                nextcolor = c + 2'd1;
        end
    endfunction

    always @(posedge clk) begin
        if (rst) begin
            phase    <= 3'd0;
            timer    <= PHASE_LEN;
            ns_state <= GREEN;
            ew_state <= RED;
        end else if (ce) begin
            if (timer != 3'd0) begin
                timer <= timer - 3'd1;
            end else begin
               // a handover into an all-red clearance phase gets the long interval
               timer <= ((phase == 3'd1) || (phase == 3'd4)) ? CLEAR_LEN : PHASE_LEN;
                case (phase)
                3'd0: begin // NS green expires -> NS yellow
                    phase    <= 3'd1;
                    ns_state <= nextcolor(ns_state);
                end
                3'd1: begin // NS yellow expires -> all red
                    phase    <= 3'd2;
                    ns_state <= nextcolor(ns_state);
                end
                3'd2: begin // all red -> EW green
                    phase    <= 3'd3;
                    ew_state <= nextcolor(ew_state);
                end
                3'd3: begin // EW green expires -> EW yellow
                    phase    <= 3'd4;
                    ew_state <= nextcolor(ew_state);
                end
                3'd4: begin // EW yellow expires -> all red
                    phase    <= 3'd5;
                    ew_state <= nextcolor(ew_state);
                end
                3'd5: begin // all red -> NS green
                    phase    <= 3'd0;
                    ns_state <= nextcolor(ns_state);
                end
                default: begin
                    phase <= phase;
                end
                endcase
            end
        end
    end

    assign o_ns_green = (ns_state == GREEN);
    assign o_ew_green = (ew_state == GREEN);
    assign o_phase    = phase;

    // P: the two roads are never green at the same time
    always @(*)
        if (ns_state == GREEN)
            assert (ew_state != GREEN);

   // Q: during the all-red clearance phases neither road may show green
   always @(posedge clk)
       if (phase == 3'd2 || phase == 3'd5)
           assert ((ns_state != GREEN) && (ew_state != GREEN));
endmodule

module rot_shadow (
    input wire clk,
    input wire i_rst,
    input wire i_ce,
    input wire i_load,
    input wire [15:0] i_data,
    output wire [15:0] o_word,
    output wire [15:0] o_shadow
);
    reg [15:0] word   = 16'h0000;
    reg [15:0] shadow = 16'h0000;
    reg [3:0]  amt    = 4'd0;

   // rotate lookahead pipeline: stage k holds the shadow value that is due
   // k+1 rotations from now, so o_shadow is driven straight off a register
   // and the rot-by-1 producer sits four stages upstream of the consumer
   reg [15:0] rot_p0 = 16'h0000;
   reg [15:0] rot_p1 = 16'h0000;
   reg [15:0] rot_p2 = 16'h0000;
   reg [15:0] rot_p3 = 16'h0000;

    always @(posedge clk)
        if (i_rst) begin
            word   <= 16'h0000;
            shadow <= 16'h0000;
            amt    <= 4'd0;
           rot_p0 <= 16'h0000;
           rot_p1 <= 16'h0000;
           rot_p2 <= 16'h0000;
           rot_p3 <= 16'h0000;
        end else if (i_ce) begin
            if (i_load) begin
                word   <= i_data;
                shadow <= i_data;
                amt    <= 4'd0;
               rot_p0 <= { i_data[14:0], i_data[15]   };
               rot_p1 <= { i_data[13:0], i_data[15:14] };
               rot_p2 <= { i_data[12:0], i_data[15:13] };
               rot_p3 <= { i_data[11:0], i_data[15:12] };
            end else begin
               shadow <= rot_p0;
               rot_p0 <= rot_p1;
               rot_p1 <= rot_p2;
               rot_p2 <= rot_p3;
               rot_p3 <= { rot_p3[14:0], rot_p3[15] };
                amt    <= amt + 4'd1;
            end
        end

    assign o_word   = word;
    assign o_shadow = shadow;

    always @(*)
        if (amt == 4'd0)
            assert (shadow == word);
endmodule

module alu_accum_slice (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    input  wire       i_sub,
    output reg  [7:0] o_result,
    output wire       o_zero
);
    reg [6:0] half;
reg [7:0] stg_res;   // ALU result in flight, written back next cycle
reg       stg_sub;   // direction latched alongside the in-flight result
reg       stg_vld;   // a writeback is pending


    initial o_result = 8'd0;
    initial half     = 7'd0;
initial stg_res  = 8'd0;
initial stg_sub  = 1'b0;
initial stg_vld  = 1'b0;

    assign o_zero = (o_result == 8'd0);

// back-to-back requests must accumulate on top of the in-flight result
wire [7:0] acc_src = stg_vld ? stg_res : o_result;

    always @(posedge clk) begin
        if (rst) begin
            o_result <= 8'd0;
            half     <= 7'd0;
stg_res  <= 8'd0;
stg_sub  <= 1'b0;
stg_vld  <= 1'b0;
end else begin
stg_vld <= i_ce;
if (i_ce) begin
stg_res <= i_sub ? (acc_src - 8'd2) : (acc_src + 8'd2);
stg_sub <= i_sub;
end
if (stg_vld) begin
o_result <= stg_res;
half     <= stg_sub ? (half - 7'd1) : (half + 7'd1);
end
        end
    end

    // P: whenever the half-step tracker is at zero, the registered ALU result is zero
    always @(posedge clk)
        if (half == 7'd0)
            assert (o_result == 8'd0);
endmodule

module lfsr_shadow_capture (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_cap,
    output wire [7:0] o_rand,
    output wire [7:0] o_shadow,
    output wire       o_shadow_valid
);
    // maximal-length 8-bit LFSR, taps at 8,6,5,4 (x^8 + x^6 + x^5 + x^4 + 1)
    reg [7:0] lfsr;
   reg [7:0] lfsr_b;
    reg [7:0] shadow;
    reg       shadow_valid;
   reg [1:0] ch_en;   // capture mixer channel enables: bit0 = gen A, bit1 = gen B

    initial lfsr         = 8'h01;
   initial lfsr_b       = 8'hA5;
    initial shadow       = 8'h00;
    initial shadow_valid = 1'b0;
   initial ch_en        = 2'b01;

    wire fb = lfsr[7] ^ lfsr[5] ^ lfsr[4] ^ lfsr[3];
   wire fb_b = lfsr_b[7] ^ lfsr_b[5] ^ lfsr_b[4] ^ lfsr_b[3];
   // shared capture port: XOR of whichever generator channels are enabled
   wire [7:0] sample = (ch_en[0] ? lfsr : 8'h00) ^ (ch_en[1] ? lfsr_b : 8'h00);

    always @(posedge i_clk) begin
        if (i_rst) begin
            lfsr <= 8'h01;
           lfsr_b <= 8'hA5;
        end else if (i_ce) begin
            lfsr <= { lfsr[6:0], fb };
           lfsr_b <= { lfsr_b[6:0], fb_b };
        end
    end

    // shadow register: snapshots the generator output on request
    always @(posedge i_clk) begin
        if (i_rst) begin
            shadow       <= 8'h00;
            shadow_valid <= 1'b0;
           ch_en        <= 2'b01;
        end else if (i_ce && i_cap) begin
           shadow       <= sample;
            shadow_valid <= 1'b1;
           // round-robin the shared port: gen A, gen B, then both mixed
           ch_en        <= (ch_en == 2'b01) ? 2'b10 :
                           (ch_en == 2'b10) ? 2'b11 : 2'b01;
        end
    end

    assign o_rand         = lfsr;
    assign o_shadow       = shadow;
    assign o_shadow_valid = shadow_valid;

    // P: once a sample has been latched, it can never be the lockup word
    always @(*)
        if (shadow_valid)
            assert (shadow != 8'h00);
endmodule

module stack_xor (
    input wire clk,
    input wire rst,
    input wire push,
    input wire pop,
    input wire [3:0] data,
    output reg [2:0] sp,
    output reg [3:0] xor_acc
);
    reg [3:0] m0, m1, m2, m3;
    reg [2:0] sp_b;
    initial begin sp = 0; xor_acc = 0; m0 = 0; m1 = 0; m2 = 0; m3 = 0; sp_b = 0; end

    wire [3:0] used = {1'b0, sp} + {1'b0, sp_b};
    wire do_push = push && !pop && (used != 4'd4);
    wire do_pop  = pop  && !push && (sp != 3'd0);
    wire do_a2b  = push && pop && (sp != 3'd0);
    wire do_b2a  = push && pop && (sp == 3'd0) && (sp_b != 3'd0);
    wire [3:0] top = (sp == 3'd1) ? m0 : (sp == 3'd2) ? m1 : (sp == 3'd3) ? m2 : m3;
    wire [3:0] b_top = (sp_b == 3'd1) ? m3 : (sp_b == 3'd2) ? m2 : (sp_b == 3'd3) ? m1 : m0;

    always @(posedge clk) begin
        if (rst) begin
            sp <= 3'd0;
            sp_b <= 3'd0;
            xor_acc <= 4'd0;
        end else if (do_push) begin
            case (sp)
                3'd0:    m0 <= data;
                3'd1:    m1 <= data;
                3'd2:    m2 <= data;
                default: m3 <= data;
            endcase
            sp <= sp + 3'd1;
            xor_acc <= xor_acc ^ data;
        end else if (do_pop) begin
            sp <= sp - 3'd1;
            xor_acc <= xor_acc ^ top;
        end else if (do_a2b) begin
            case (sp_b)
                3'd0:    m3 <= top;
                3'd1:    m2 <= top;
                3'd2:    m1 <= top;
                default: m0 <= top;
            endcase
            sp   <= sp - 3'd1;
            sp_b <= sp_b + 3'd1;
            xor_acc <= xor_acc ^ top;
        end else if (do_b2a) begin
            m0 <= b_top;
            sp <= 3'd1;
            sp_b <= sp_b - 3'd1;
            xor_acc <= xor_acc ^ b_top;
        end
    end

    always @(posedge clk)
        if (sp == 3'd0)
            assert (xor_acc == 4'd0);
endmodule

module prio_pipe (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [7:0] req,
    output reg b_valid,
    output reg [2:0] b_idx
);
    reg [7:0] a_vec;
    reg       a_valid;
    reg [7:0] b_vec;
   reg [2:0] s_idx;    // runner-up index into the vector held at the grant port
   reg       s_valid;  // a runner-up grant is pending for that vector

    initial begin
        a_vec = 8'h00; a_valid = 1'b0;
        b_vec = 8'h00; b_idx = 3'd0; b_valid = 1'b0;
       s_idx = 3'd0; s_valid = 1'b0;
    end

    // combinational priority encode of the stage-1 vector (default index 0)
    wire [2:0] a_idx = a_vec[7] ? 3'd7 :
                       a_vec[6] ? 3'd6 :
                       a_vec[5] ? 3'd5 :
                       a_vec[4] ? 3'd4 :
                       a_vec[3] ? 3'd3 :
                       a_vec[2] ? 3'd2 :
                       a_vec[1] ? 3'd1 : 3'd0;

   // second-pass encode: strip the winning bit, encode the next-highest request
   wire [7:0] a_rem  = a_vec & ~(8'h01 << a_idx);
   wire [2:0] a2_idx = a_rem[7] ? 3'd7 :
                       a_rem[6] ? 3'd6 :
                       a_rem[5] ? 3'd5 :
                       a_rem[4] ? 3'd4 :
                       a_rem[3] ? 3'd3 :
                       a_rem[2] ? 3'd2 :
                       a_rem[1] ? 3'd1 : 3'd0;

    always @(posedge clk) begin
        if (rst) begin
            a_vec <= 8'h00; a_valid <= 1'b0;
            b_vec <= 8'h00; b_idx <= 3'd0; b_valid <= 1'b0;
           s_idx <= 3'd0; s_valid <= 1'b0;
        end else if (ce) begin
            a_vec   <= req;
            a_valid <= (req != 8'h00);
           if (a_valid) begin
               // stage-1 winner owns the grant port; queue its runner-up
               b_vec   <= a_vec;
               b_idx   <= a_idx;
               b_valid <= 1'b1;
               s_idx   <= a2_idx;
               s_valid <= (a_rem != 8'h00);
           end else if (s_valid) begin
               // grant port would idle: reissue held vector with runner-up index
               b_idx   <= s_idx;
               b_valid <= 1'b1;
               s_idx   <= 3'd0;
               s_valid <= 1'b0;
           end else begin
               b_vec   <= 8'h00;
               b_idx   <= 3'd0;
               b_valid <= 1'b0;
           end
        end
    end

    always @(posedge clk)
        if (b_valid)
            assert (b_vec[b_idx]);
endmodule

module token_bucket (
    input wire clk,
    input wire rst,
    input wire drip,
    input wire spend,
    output reg [2:0] tokens,
    output reg tokens_hi
);
    wire drip_en  = drip  && (tokens != 3'd4);
    wire spend_en = spend && (tokens != 3'd0);
    wire inc = drip_en && !spend_en;
    wire dec = spend_en && !drip_en;

    initial tokens   = 3'd0;
    initial tokens_hi = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            tokens    <= 3'd0;
            tokens_hi <= 1'b0;
        end else begin
            if (inc)      tokens <= tokens + 3'd1;
            else if (dec) tokens <= tokens - 3'd1;

            if (inc && tokens == 3'd1)      tokens_hi <= 1'b1;
            else if (dec && tokens == 3'd2) tokens_hi <= 1'b0;
        end
    end

    always @(posedge clk)
        if (tokens_hi) assert (tokens != 3'd0);
endmodule

module token_bucket_pool (
    input  wire       clk,
    input  wire       rst,
    input  wire [5:0] drip_req,
    input  wire [5:0] spend_req,
    output reg  [3:0] pool,
    output wire [5:0] hi_flags,
    output reg        starved
);
    localparam [3:0] TOTAL = 4'd8;

   // adaptive credit window: TOTAL is the nominal budget, but a starvation
   // event retires one credit from circulation until the pool goes idle again
   reg [3:0] budget;
   reg       shrink_pend;

    // per-instance observable state
    wire [2:0] t0, t1, t2, t3, t4, t5;
    wire       h0, h1, h2, h3, h4, h5;

    // a bucket wants a credit only if the drip would really land:
    // not already full, and not cancelled by a concurrent accepted spend
    wire [5:0] want;
    assign want[0] = drip_req[0] && (t0 != 3'd4) && !(spend_req[0] && (t0 != 3'd0));
    assign want[1] = drip_req[1] && (t1 != 3'd4) && !(spend_req[1] && (t1 != 3'd0));
    assign want[2] = drip_req[2] && (t2 != 3'd4) && !(spend_req[2] && (t2 != 3'd0));
    assign want[3] = drip_req[3] && (t3 != 3'd4) && !(spend_req[3] && (t3 != 3'd0));
    assign want[4] = drip_req[4] && (t4 != 3'd4) && !(spend_req[4] && (t4 != 3'd0));
    assign want[5] = drip_req[5] && (t5 != 3'd4) && !(spend_req[5] && (t5 != 3'd0));

   // a retire cycle pulls its credit straight out of the pool by consuming
   // that cycle's grant slot; the credit comes back when the pool is idle
   wire win_shrink = shrink_pend && (budget == TOTAL) && (pool != 4'd0);
   wire win_grow   = (budget != TOTAL) && (pool == budget);
   wire credit_avail = (pool != 4'd0) && !win_shrink;

    // one credit per cycle, fixed priority
    wire [5:0] grant;
    assign grant[0] = credit_avail && want[0];
    assign grant[1] = credit_avail && want[1] && !want[0];
    assign grant[2] = credit_avail && want[2] && !want[0] && !want[1];
    assign grant[3] = credit_avail && want[3] && !want[0] && !want[1] && !want[2];
    assign grant[4] = credit_avail && want[4] && !want[0] && !want[1] && !want[2] && !want[3];
    assign grant[5] = credit_avail && want[5] && !want[0] && !want[1] && !want[2] && !want[3] && !want[4];
    wire grant_any = grant[0] || grant[1] || grant[2] || grant[3] || grant[4] || grant[5];

    // a released token returns its credit
    wire [5:0] rel;
    assign rel[0] = spend_req[0] && (t0 != 3'd0) && !(grant[0] && (t0 != 3'd4));
    assign rel[1] = spend_req[1] && (t1 != 3'd0) && !(grant[1] && (t1 != 3'd4));
    assign rel[2] = spend_req[2] && (t2 != 3'd0) && !(grant[2] && (t2 != 3'd4));
    assign rel[3] = spend_req[3] && (t3 != 3'd0) && !(grant[3] && (t3 != 3'd4));
    assign rel[4] = spend_req[4] && (t4 != 3'd0) && !(grant[4] && (t4 != 3'd4));
    assign rel[5] = spend_req[5] && (t5 != 3'd0) && !(grant[5] && (t5 != 3'd4));

    wire [3:0] rel_cnt = {3'd0, rel[0]} + {3'd0, rel[1]} + {3'd0, rel[2]} +
                         {3'd0, rel[3]} + {3'd0, rel[4]} + {3'd0, rel[5]};

    token_bucket u0 (.clk(clk), .rst(rst), .drip(grant[0]), .spend(spend_req[0]), .tokens(t0), .tokens_hi(h0));
    token_bucket u1 (.clk(clk), .rst(rst), .drip(grant[1]), .spend(spend_req[1]), .tokens(t1), .tokens_hi(h1));
    token_bucket u2 (.clk(clk), .rst(rst), .drip(grant[2]), .spend(spend_req[2]), .tokens(t2), .tokens_hi(h2));
    token_bucket u3 (.clk(clk), .rst(rst), .drip(grant[3]), .spend(spend_req[3]), .tokens(t3), .tokens_hi(h3));
    token_bucket u4 (.clk(clk), .rst(rst), .drip(grant[4]), .spend(spend_req[4]), .tokens(t4), .tokens_hi(h4));
    token_bucket u5 (.clk(clk), .rst(rst), .drip(grant[5]), .spend(spend_req[5]), .tokens(t5), .tokens_hi(h5));

    assign hi_flags = {h5, h4, h3, h2, h1, h0};

    initial pool    = TOTAL;
   initial budget      = TOTAL;
   initial shrink_pend = 1'b0;
    initial starved = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            pool    <= TOTAL;
           budget      <= TOTAL;
           shrink_pend <= 1'b0;
            starved <= 1'b0;
        end else begin
           pool <= pool + rel_cnt - {3'd0, grant_any}
                                  - {3'd0, win_shrink} + {3'd0, win_grow};
           if (win_shrink)    budget <= budget - 4'd1;
           else if (win_grow) budget <= TOTAL;
           if (win_shrink)                           shrink_pend <= 1'b0;
           else if (pool == 4'd0 && budget == TOTAL) shrink_pend <= 1'b1;
            if (pool == 4'd0) starved <= 1'b1;
        end
    end

    // when the pool is exhausted all credits sit in the buckets, so at least
    // one bucket must be above its high-water mark
    always @(posedge clk)
        if (pool == 4'd0)
            assert (h0 || h1 || h2 || h3 || h4 || h5);

   // with seven or more credits still in the pool at most one token is
   // outstanding, so no bucket can have reached its high-water mark
   always @(posedge clk)
       if (pool >= 4'd7)
           assert (hi_flags == 6'd0);
endmodule

module ring_occ (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    output reg  [2:0] count,
    output reg  [3:0] occ
);
    reg [1:0] wptr, rptr;
   reg [1:0] bwptr, brptr;
   reg [2:0] bcount;
   reg [3:0] bocc;
   reg [2:0] credit;
   reg       sel, psel;
    initial begin wptr = 2'd0; rptr = 2'd0; count = 3'd0; occ = 4'b0000; end
   initial begin bwptr = 2'd0; brptr = 2'd0; bcount = 3'd0; bocc = 4'b0000; credit = 3'd4; sel = 1'b0; psel = 1'b0; end

   wire push_ok = push && (credit != 3'd0);
   wire do_push = push_ok && !sel;
   wire push_b  = push_ok &&  sel;
   wire pop_b   = pop && bocc[brptr] && (psel || (count == 3'd0));
   wire do_pop  = pop && (count != 3'd0) && !pop_b;

    wire [3:0] set_bit = do_push ? (4'b0001 << wptr) : 4'b0000;
    wire [3:0] clr_bit = do_pop  ? (4'b0001 << rptr) : 4'b0000;
   wire [3:0] bset_bit = push_b ? (4'b0001 << bwptr) : 4'b0000;
   wire [3:0] bclr_bit = pop_b  ? (4'b0001 << brptr) : 4'b0000;

    always @(posedge clk) begin
        if (rst) begin
            wptr  <= 2'd0;
            rptr  <= 2'd0;
            count <= 3'd0;
            occ   <= 4'b0000;
           bwptr  <= 2'd0;
           brptr  <= 2'd0;
           bcount <= 3'd0;
           bocc   <= 4'b0000;
           credit <= 3'd4;
           sel    <= 1'b0;
           psel   <= 1'b0;
        end else begin
            if (do_push) wptr <= wptr + 2'd1;
            if (do_pop)  rptr <= rptr + 2'd1;
            occ <= (occ | set_bit) & ~clr_bit;
            case ({do_push, do_pop})
                2'b10:   count <= count + 3'd1;
                2'b01:   count <= count - 3'd1;
                default: count <= count;
            endcase
           if (push_b) bwptr <= bwptr + 2'd1;
           if (pop_b)  brptr <= brptr + 2'd1;
           bocc <= (bocc | bset_bit) & ~bclr_bit;
           case ({push_b, pop_b})
               2'b10:   bcount <= bcount + 3'd1;
               2'b01:   bcount <= bcount - 3'd1;
               default: bcount <= bcount;
           endcase
           case ({push_ok, do_pop || pop_b})
               2'b10:   credit <= credit - 3'd1;
               2'b01:   credit <= credit + 3'd1;
               default: credit <= credit;
           endcase
           if (push_ok) sel <= ~sel;
           if (do_pop)     psel <= 1'b1;
           else if (pop_b) psel <= 1'b0;
        end
    end

    always @(posedge clk)
        if (count == 3'd1)
            assert (occ == 4'b0001 || occ == 4'b0010 ||
                    occ == 4'b0100 || occ == 4'b1000);
endmodule

module vend_credit (
    input wire clk,
    input wire i_reset,
    input wire i_ce,
    input wire i_dime,
    output wire o_dispense,
    output wire [5:0] o_change
);
    reg [3:0] units = 0;      // credit in 5-cent units
reg [3:0] cred_tens = 0;  // credit in cents, tens BCD digit (display)
reg [3:0] cred_ones = 0;  // credit in cents, ones BCD digit (display)
    reg       dispense = 0;
    reg [5:0] change = 0;

    wire [3:0] inc_u = i_dime ? 4'd2  : 4'd1;
    wire [5:0] inc_c = i_dime ? 6'd10 : 6'd5;
    wire [3:0] nu = units + inc_u;
wire [7:0] cred_c    = cred_tens * 8'd10 + cred_ones;
wire [7:0] nc        = cred_c + inc_c;
// BCD carry propagation when the coin is just added to the credit
wire [4:0] ones_sum  = cred_ones + (i_dime ? 4'd0 : 4'd5);
wire       ones_cy   = (ones_sum >= 5'd10);
wire [3:0] ones_next = ones_cy ? (ones_sum - 5'd10) : ones_sum[3:0];
wire [3:0] tens_next = cred_tens + (i_dime ? 4'd1 : 4'd0) + ones_cy;
// leftover credit after a 25c vend, renormalised back into BCD
wire [7:0] rem       = nc - 8'd25;
wire       rem_cy    = (rem >= 8'd10);
wire [3:0] rem_tens  = rem_cy ? 4'd1 : 4'd0;
wire [3:0] rem_ones  = rem_cy ? (rem[3:0] - 4'd10) : rem[3:0];

    always @(posedge clk)
        if (i_reset) begin
            units    <= 4'd0;
cred_tens <= 4'd0;
cred_ones <= 4'd0;
            dispense <= 1'b0;
            change   <= 6'd0;
        end else if (i_ce) begin
            if (nu >= 4'd5) begin
                units    <= nu - 4'd5;
cred_tens <= rem_tens;
cred_ones <= rem_ones;
change    <= rem[5:0];
                dispense <= 1'b1;
            end else begin
                units    <= nu;
cred_tens <= tens_next;
cred_ones <= ones_next;
                dispense <= 1'b0;
            end
        end

    assign o_dispense = dispense;
    assign o_change   = change;

    always @(posedge clk)
        if (dispense) assert (change <= 6'd5);
endmodule

module token_bucket (
    input  wire clk,
    input  wire rst,
    input  wire ce,
    input  wire req,
    input  wire drip,
    output wire grant
);
    reg [3:0] tokens = 4'd8;   // tokens currently in the bucket
    reg [3:0] free   = 4'd0;   // room left in the bucket (shadow accounting)
    reg [3:0] cap    = 4'd8;   // current burst allowance (adaptive capacity)

    wire spend   = ce && req  && (tokens != 4'd0);
    wire refill  = ce && drip && (free   != 4'd0);
    // starved: a request found the bucket empty, so hand a retired slot back
    wire restore = ce && req && (tokens == 4'd0) && (cap != 4'd8);
    // fully idle with room going unused: retire one slot of allowance
    wire reclaim = ce && !req && !drip && (free != 4'd0) && (cap != 4'd4);

    assign grant = spend;

    always @(posedge clk) begin
        if (rst) begin
            tokens <= 4'd8;
            free   <= 4'd0;
            cap    <= 4'd8;
        end else begin
            tokens <= tokens - spend + refill;
            free   <= free   + spend - refill + restore - reclaim;
            cap    <= cap    + restore - reclaim;
        end
    end

    // P: if the bucket is not completely full, at least one slot's worth of
    // tokens is missing, so occupancy cannot exceed CAP-1.
    always @(posedge clk)
        if (free != 4'd0)
            assert (tokens <= 4'd7);
endmodule
